create temporary table import_summary (wikidata_id text primary key, summary text not null, source text not null);

insert into import_summary (wikidata_id, summary, source) values
  ('Q3317627', 'Mobile Suit Gundam SEED: Battle Assault est un jeu vidéo de combat développé et édité par Bandai en août 2004 sur Game Boy Advance. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et c''est le quatrième opus d''une série composée de cinq jeux vidéo de combat.', 'https://fr.wikipedia.org/wiki/Mobile_Suit_Gundam_SEED:_Battle_Assault'),
  ('Q3317633', 'Mobile Suit Gundam SEED: Tomo to Kimi to Koko de est un jeu vidéo d''action développé et édité par Bandai en mai 2004 sur Game Boy Advance. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Gundam SEED.', 'https://fr.wikipedia.org/wiki/Mobile_Suit_Gundam_SEED:_Tomo_to_Kimi_to_Koko_de'),
  ('Q3324551', 'Mortal Kombat Advance (communément abrégé MKA) est un jeu vidéo de combat développé par la société Virtucraft. C''est une version « réduite » de Ultimate Mortal Kombat 3, avec lequel MKA partage l''histoire et les personnages. Cependant, le jeu fut mal accueilli par la critique comme par les joueurs.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat_Advance'),
  ('Q3038709', 'Dragon Ball Z: Taiketsu est un jeu vidéo de combat développé par Webfoot sur l''univers de Dragon Ball Z. Le jeu est distribué à partir de 2003 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_Taiketsu'),
  ('Q3042524', 'Mega Man Zero 3 (Rockman Zero 3 au Japon) est un jeu d''action-plates-formes développé par Inti Creates et édité par Capcom en 2004 sur Game Boy Advance. Il fait partie de la franchise Mega Man et est le troisième de la série dérivée Mega Man Zero. Il est réédité dans la compilation Mega Man Zero Collection sur Nintendo DS en 2010 et sur la console virtuelle de la Wii U en 2015.', 'https://fr.wikipedia.org/wiki/Mega_Man_Zero_3'),
  ('Q3038705', 'Dragon Ball GT: Transformation est un jeu vidéo de combat, édité par Atari Inc. et développé par Webfoot, sorti sur Game Boy Advance le 9 août 2005.

Une suite sur la même plate-forme, Dragon Ball GT: Transformation 2, a été annulée.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_GT:_Transformation'),
  ('Q3038740', 'Dragon Ball Z: L’Héritage de Goku 2 (Dragon Ball Z: The Legacy of Goku II) est un jeu vidéo d’action-aventure développé par Webfoot Technologies et édité par Infogrames sur Game Boy Advance, sorti en 2003.

C’est le deuxième volet de la série L’Héritage de Goku.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z_:_L%27H%C3%A9ritage_de_Goku_2'),
  ('Q3038752', 'Dragon Quest Monsters: Caravan Heart est un jeu vidéo développé par TOSE en 2003 sur Game Boy Advance pour l''éditeur japonais Enix.', 'https://fr.wikipedia.org/wiki/Dragon_Quest_Monsters:_Caravan_Heart'),
  ('Q3010914', 'Dragon Ball: Advanced Adventure est un jeu vidéo d''action-aventure, développé par Dimps sur l''univers de Dragon Ball. Le jeu est publié sur Game Boy Advance au Japon le 18 novembre 2004, en Europe le 17 juin 2005 et aux États-Unis, le 6 juin 2006.', 'https://fr.wikipedia.org/wiki/Dragon_Ball:_Advanced_Adventure'),
  ('Q3030331', 'Disney''s Party (parfois nommé Disney Party) est un jeu vidéo de type party game sorti en 2002 sur GameCube et Game Boy Advance. Il est basé sur le même mode de jeu que la série Mario Party.

Le jeu a été développé par Neverland / Hudson Soft sur GameCube, Jupiter sur Game Boy Advance, et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/Disney%27s_Party'),
  ('Q2748684', 'Sonic Advance 2 est un jeu de plates-formes développé par Dimps sous la supervision de Sonic Team, et édité par Sega sur Game Boy Advance. Il est sorti le 19 décembre 2002 au Japon, puis le 9 mars 2003 en Amérique du Nord et le 28 mars en Europe.', 'https://fr.wikipedia.org/wiki/Sonic_Advance_2'),
  ('Q1000547', 'Yggdra Union: We''ll Never Fight Alone est un Tactical RPG édité sur Game Boy Advance et sur Playstation Portable.

Il a été développé par Sting Entertainment et est connu comme le second épisode de la série Dept. Heaven. Les deux versions du jeu ont été localisées par Atlus USA en Amérique du Nord et 505 Games a publié la version Game Boy Advance dans quelques pays européens. L''on dénombre trois spin-off de ce jeu, dont aucun n''a quitté le Japon. Le premier est paru sur mobile et Nintendo DS sous le nom de Yggdra Unison: Seiken Buxtehude Japon tandis que le second, qui n''a pas non plus quitté ce pays, est nommé Blaze Union: Story to Reach the Future. Le premier est une sorte de scénario alternatif à Yggdra Union, le second est une préquelle au jeu original. Le troisième spinn-off, Gloria Union, n''a pas de lien scénaristique avec les autres opus.', 'https://fr.wikipedia.org/wiki/Yggdra_Union:_We%27ll_Never_Fight_Alone'),
  ('Q2905266', 'Black/Matrix Zero est un jeu de rôle tactique développé par Flight-Plan et publié par NEC InterChannel sur Game Boy Advance et sorti le 30 août 2002 au Japon.', 'https://fr.wikipedia.org/wiki/Black/Matrix_Zero'),
  ('Q3023252', 'Densetsu no Starfy est un jeu vidéo de plates-formes développé par TOSE et édité par Nintendo, sorti sur Game Boy Advance en 2002 uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Densetsu_no_Starfy'),
  ('Q3057552', 'Kirby: Cauchemar au Pays des Rêves est un jeu vidéo de plate-forme sorti en 2002, mettant en scène Kirby de Nintendo. Il a été développé à l''occasion des dix ans de la série Kirby (le premier jeu Kirby étant sorti en 1992).

Ce jeu est l''adaptation sur Game Boy Advance de Kirby''s Adventure, second épisode des aventures de Kirby (sorti sur NES en 1993).

Cette version contient des graphismes remaniés, de nouveaux mini-jeux accessibles à 4 joueurs, quelques passages inédits et de petites modifications de gameplay.', 'https://fr.wikipedia.org/wiki/Kirby_:_Cauchemar_au_Pays_des_R%C3%AAves'),
  ('Q1005552', 'Riviera: La Terre Promise ou Riviera: The Promised Land est un jeu vidéo de rôle sorti à l''origine sur la console WonderSwan en 2002 avant d''être porté sur Game Boy Advance en 2005 puis sur PlayStation Portable en 2006.

Le jeu combine des éléments classiques de jeux vidéo de rôle (croissance des personnages, collecte d''objets et d''armes, donjons), de jeux d''aventures (puzzles et énigmes, en large majorité sous forme de mini-jeux) et de jeux de dragues (à part Ein le personnage principal, masculin, l''équipe n''est composé que de filles et en fonction des choix du joueur lors des dialogues, Ein finira le jeu avec l''une d''entre elles ou avec aucune).', 'https://fr.wikipedia.org/wiki/Riviera_:_La_Terre_Promise'),
  ('Q3035980', 'Donald Duck Couak Attack, stylisé Donald Duck: Cou@k Att@ck ?*!, également intitulé Donald Duck: Goin'' Qu@ckers en Amérique du Nord, est un jeu vidéo de plates-formes développé par Ubisoft Montréal et Disney Interactive, publié par Ubi Soft Entertainment, originellement publié en 2000 sur PC ainsi que sur consoles Dreamcast, Nintendo 64, PlayStation, et Game Boy. Le jeu est réédité et publié en 2002 sur consoles PlayStation 2 et GameCube.', 'https://fr.wikipedia.org/wiki/Donald_Duck_Couak_Attack'),
  ('Q3027775', 'Digimon Battle Spirit est un jeu de combat développé par Dimps et édité par Bandai, appartenant à la franchise japonaise Digimon. Le jeu est exclusivement distribué dans les marchés japonais sur console WonderSwan Color sous le nom de Digimon Tamers: Battle Spirit. Deux ans plus tard, le jeu est importé sur Game Boy Advance en Europe, puis aux États-Unis.

Le jeu met en scène les personnages et les digimon protagonistes des trois premières saisons de l''anime dans un jeu d''action au scénario néanmoins simpliste et aux fonds musicaux à la base tirés de l''anime. Le système de jeu est similaire à celui de Digimon Rumble Arena sur console PlayStation. Le jeu met en pratique les accessoires USB ou câble link pour un mode multijoueur de maximum deux personnes.', 'https://fr.wikipedia.org/wiki/Digimon_Battle_Spirit'),
  ('Q3024823', 'Dragon Ball Z: Buu''s Fury est un jeu vidéo d’action-aventure développé par Webfoot Technologies et édité par Atari Inc. sur Game Boy Advance, sorti en 2004.

C’est la suite de Dragon Ball Z: L''Héritage de Goku II pour Game Boy Advance. C’est le troisième volet dans la trilogie L’Héritage de Goku, même si celui-ci ne porte pas le nom de la trilogie.

Le jeu suit la saga Boo à partir de l’épisode 195 et se termine à l’épisode 291. Le joueur commence dans la saga du tournoi de l’autre-monde et finit à la saga Petit Boo.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_Buu%27s_Fury'),
  ('Q3459383', 'SD Gundam: G Generation Advance est un jeu vidéo de stratégie développé et édité par Bandai en novembre 2003 sur Game Boy Advance. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam.', 'https://fr.wikipedia.org/wiki/SD_Gundam:_G_Generation_Advance'),
  ('Q3459411', 'SD Gundam Force est un jeu vidéo de tir au pistolet développé et édité par Bandai en mai 2004 sur Game Boy Advance. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam et SD Gundam Force.', 'https://fr.wikipedia.org/wiki/SD_Gundam_Force'),
  ('Q3482216', 'Shining Force: Resurrection of the Dark Dragon est un jeu vidéo tactical RPG sorti en 2004 sur Game Boy Advance. Le jeu a été développé par Amusement Vision (un studio Sega) et édité par THQ, il s''agit d''un remake du jeu Shining Force.', 'https://fr.wikipedia.org/wiki/Shining_Force:_Resurrection_of_the_Dark_Dragon'),
  ('Q150180', 'Fire Emblem: The Blazing Blade, connu au Japon sous le nom de Fire Emblem: Rekka no Ken et intitulé simplement Fire Emblem en Occident, est un jeu vidéo de rôle tactique sur Game Boy Advance, sorti le 25 avril 2003 au Japon, le 3 novembre 2003 en Amérique du Nord, le 20 février 2004 en Australie et le 16 juillet 2004 en Europe. Développé par Intelligent Systems et édité par Nintendo, c''est le septième épisode de la série Fire Emblem.

Il s''agit du premier opus de la franchise à franchir les frontières du Japon, raison pour laquelle le titre a été raccourci. Afin d''éviter toute confusion, Intelligent Systems lui appose régulièrement le sous-titre rétroactif The Blazing Blade pour le désigner. Cet épisode conte les aventures de Lyn, Eliwood et Hector, et son histoire est la préquelle de Fire Emblem: The Binding Blade, sorti l''année précédente sur la même plate-forme.', 'https://fr.wikipedia.org/wiki/Fire_Emblem:_The_Blazing_Blade'),
  ('Q2878408', 'Back to Stone est un jeu vidéo d''action-aventure développé par Hidden Floor et édité par Neko Entertainment, sorti à partir de 2006 sur Game Boy Advance.

Il s''agit de l''unique jeu de Hidden Floor, développé à Bordeaux par une équipe d''anciens de Kalisto Entertainment.', 'https://fr.wikipedia.org/wiki/Back_to_Stone'),
  ('Q3201635', 'L''Aigle de guerre est un jeu vidéo de stratégie en temps réel développé par Genki et édité par Nintendo, sorti en 2001 sur Game Boy Advance. Il était disponible au lancement de la console au Japon. Il est sorti en Europe mais est inédit aux États-Unis. Il s''inspire de la vie et des campagnes militaires de Napoléon Ier, sans se soucier de la vérité historique.', 'https://fr.wikipedia.org/wiki/L%27Aigle_de_guerre'),
  ('Q3091529', 'Mega Man Battle Network 2 est un tactical RPG développé par Capcom Production Studio 2 et édité par Capcom en 2002 sur Game Boy Advance. C''est le second volet de la série Mega Man Battle Network. Il est réédité en 2014 sur la console virtuelle de la Wii U.', 'https://fr.wikipedia.org/wiki/Mega_Man_Battle_Network_2'),
  ('Q2081510', 'Sonic Advance est un jeu de plates-formes développé par Dimps sous la supervision de Sonic Team, et édité par Sega sur Game Boy Advance au Japon le 20 décembre 2001, puis le 4 février 2002 en Amérique du Nord et le 23 mars 2002 en Europe pour célébrer les dix ans de la franchise en parallèle de Sonic Adventure 2. Il est le premier jeu Sonic à être sorti sur une console de Nintendo.

Cet opus marque le retour aux origines de la série: la deux dimensions. Un portage titré Sonic N est réalisé en 2003 pour la N-Gage de Nokia. Il permet de jouer avec Sonic the Hedgehog, Miles "Tails" Prower, Knuckles the Echidna et Amy Rose.', 'https://fr.wikipedia.org/wiki/Sonic_Advance'),
  ('Q1091127', 'Oddworld: Munch''s Oddysee est un jeu vidéo sorti le 15 novembre 2001 aux États-Unis, le 22 février 2002 au Japon et le 14 mars 2002 en Europe. Toujours développé par Oddworld Inhabitants, et cette fois édité par Microsoft Games, le jeu faisait partie du line-up de la Xbox et est donc sorti en même temps. Une version, développée par THQ et éditée par Nintendo est sortie le 24 octobre 2003 sur Game Boy Advance, sous le même nom. Le jeu devait également sortir sur PlayStation 2, mais a été annulé. Cependant, un pack contenant les deux premiers jeux Oddworld sortis sur PlayStation et PC, ainsi qu''une version pour PC des jeux Munch''s Oddysee et La Fureur de l''étranger est sorti en 2010 et est disponible via la plate-forme de téléchargement Steam.', 'https://fr.wikipedia.org/wiki/Oddworld_:_L%27Odyss%C3%A9e_de_Munch'),
  ('Q3327153', 'Mr. Driller 2 est un jeu vidéo de réflexion développé et édité par Namco sorti en 2001 sur Game Boy Advance au Japon. Il est inédit en Europe et est sorti tardivement aux États-Unis. Il était disponible au lancement de la console au Japon.', 'https://fr.wikipedia.org/wiki/Mr._Driller_2'),
  ('Q3400938', 'Power Pro Kun Pocket 3 est un jeu vidéo de baseball développé et édité par Konami, sorti en 2001 sur Game Boy Advance uniquement au Japon. Il s''agit du premier jeu de cette série sur Game Boy Advance et était disponible au lancement de la console. Il fait partie de la série Jikkyō Powerful Pro Yakyū.', 'https://fr.wikipedia.org/wiki/Power_Pro_Kun_Pocket_3'),
  ('Q150169', 'Fire Emblem: The Sacred Stones est un jeu vidéo de rôle tactique sorti sur Game Boy Advance, développé par Intelligent Systems et publié par Nintendo en 2004. Il s''agit du huitième jeu de la série Fire Emblem, du dernier sorti sur la console et du second à être publié en Europe et en Amérique du Nord.

Le joueur y suit les aventures des jumeaux Eirika et Ephraim qui doivent libérer le continent de Magvel de sa malédiction et reconstruire leur nation ravagée par la guerre. Il est très proche de son prédécesseur tant au niveau du gameplay qu''au niveau des graphismes.', 'https://fr.wikipedia.org/wiki/Fire_Emblem:_The_Sacred_Stones'),
  ('Q1091226', 'Super Mario Ball, connu en Amérique du Nord sous le nom de Mario Pinball Land, est un jeu vidéo de flipper édité par Nintendo et développé par Fuse Games. Il est sorti en 2004 au Japon, en Amérique du Nord puis en Europe sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Super_Mario_Ball'),
  ('Q3154355', 'Iridion 3D est un jeu vidéo développé par Shin''en et édité par Majesco, sorti en 2001 sur Game Boy Advance. Il s''agit d''un rail shooter et du premier shoot them up sorti sur la console. Initialement prévu sur Game Boy Color, il est finalement développé sur la nouvelle console de Nintendo, ce qui lui permet d''arborer des graphismes en pseudo-3D. Les graphismes et la musique sont considérés comme les points forts du titre. Le jeu s''est bien vendu malgré l''accueil mitigé de son gameplay par la presse spécialisée. Il a donc connu une suite, Iridion II, et représente le premier jeu d''une lignée de shoot them up sur consoles portables développés par Shin''en.', 'https://fr.wikipedia.org/wiki/Iridion_3D'),
  ('Q3336144', 'Naruto: Ninja Council 2 est un jeu vidéo de type beat them all développé par Aspect et édité par Tomy, sorti en 2004 sur Game Boy Advance. Il est également disponible sur Nintendo DS.

Le jeu fait suite à Naruto: Ninja Council.', 'https://fr.wikipedia.org/wiki/Naruto:_Ninja_Council_2'),
  ('Q3156758', 'J.League Pocket est un jeu vidéo de football développé et édité par Konami, sorti en 2001 sur Game Boy Advance. Le jeu est disponible au lancement de la console.

Il a connu une suite: J.League Pocket 2.', 'https://fr.wikipedia.org/wiki/J.League_Pocket'),
  ('Q1072868', 'Sorti en France et en Europe le 24 octobre 2003 (au Japon, le 28 mars 2003 et aux États-Unis, le 7 septembre), Final Fantasy Tactics Advance est l''un des tout premiers Tactical RPG de la Game Boy Advance. Il reprend le système du jeu de Final Fantasy Tactics premier du nom, sorti en 1997 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_Tactics_Advance'),
  ('Q2086466', 'Mario Golf: Advance Tour, connu au Japon sous le nom de Mario Golf: GBA Tour est un jeu vidéo de golf sorti sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Mario_Golf:_Advance_Tour'),
  ('Q2878969', 'Kururin Paradise est un jeu vidéo d''action et de réflexion développé par Eighting et édité par Nintendo, sorti exclusivement au Japon en 2002 sur Game Boy Advance.

Le 14 octobre 2026, le titre est ajouté au catalogue Game Boy Advance du Nintendo Switch Online, rendant pour la première fois disponible le jeu hors du Japon.', 'https://fr.wikipedia.org/wiki/Kururin_Paradise'),
  ('Q3108749', 'Mother, ou EarthBound en dehors du Japon, est une série de jeux vidéo de rôle japonais éditée par Nintendo, constituée de trois jeux: Mother, EarthBound, Mother 3.', 'https://fr.wikipedia.org/wiki/Mother_(s%C3%A9rie_de_jeux_vid%C3%A9o)'),
  ('Q1153949', 'Tomb Raider: The Prophecy est un jeu vidéo d''action-aventure développé par Ubisoft Milan et édité par Ubisoft (sous licence d''Eidos Interactive et Core Design), sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Tomb_Raider:_The_Prophecy'),
  ('Q1313985', 'Harvest Moon: Friends of Mineral Town est un jeu vidéo de type Simulation de vie / RPG développé par Marvelous Interactive, sorti en 2003 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Harvest_Moon:_Friends_of_Mineral_Town'),
  ('Q2819910', 'A Sound of Thunder est un jeu vidéo d''action-aventure développé par Mobius Entertainment et édité par BAM! Entertainment, sorti en 2004 sur Game Boy Advance. Il s''agit d''une adaptation du film Un coup de tonnerre de Peter Hyams, lui-même basé sur la nouvelle du même nom de Ray Bradbury.

Le jeu était initialement prévu sur Xbox, GameCube et PlayStation 2 mais sa sortie fut annulée sur ces différents supports.', 'https://fr.wikipedia.org/wiki/A_Sound_of_Thunder_(jeu_vid%C3%A9o)'),
  ('Q3093444', 'GT Advance Championship Racing, appelé Advance GTA au Japon, est un jeu vidéo de course développé par MTO, sorti en 2001 sur Game Boy Advance. C''est le premier épisode de la série GT. Il était disponible au lancement de la console.', 'https://fr.wikipedia.org/wiki/GT_Advance_Championship_Racing'),
  ('Q3197899', 'Klonoa 2: Dream Champ Tournament est un jeu vidéo de plates-formes développé et édité par Namco, sorti en 2002 sur Game Boy Advance. Ce jeu est le cinquième de la série Klonoa et le deuxième à sortir sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Klonoa_2:_Dream_Champ_Tournament'),
  ('Q3197902', 'Klonoa Heroes: Legend of the Star Medal est un jeu vidéo d''action-RPG développé et édité par Namco, sorti en 2002 sur Game Boy Advance et uniquement au Japon. Ce jeu est le sixième de la série Klonoa et le troisième à sortir sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Klonoa_Heroes:_Legend_of_the_Star_Medal'),
  ('Q2259234', 'Mortal Kombat: Tournament Edition (communément abrégé MK:TE) est un jeu vidéo de combat de la série Mortal Kombat. Il a été développé et produit par Midway, et il est sorti seulement Game Boy Advance. C''est un portage de Mortal Kombat: Deadly Alliance mais forcément moins dense compte tenu de la capacité réduite de la cartouche de jeu de la Game Boy Advance. Trois nouveaux personnages y font néanmoins leur apparition.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat:_Tournament_Edition'),
  ('Q4728774', 'Razbitume ! Restez branchés ! (All Grown Up! Express Yourself) est un jeu vidéo d''action-aventure développé par Altron et édité par THQ, sorti en 2004 sur Game Boy Advance. Il est basé sur la série télévisée d''animation du même nom.', 'https://fr.wikipedia.org/wiki/Razbitume_!_Restez_branch%C3%A9s_!'),
  ('Q3282480', 'Summon Night: Swordcraft Story est un jeu vidéo de type action-RPG développé par Flight-Plan et sorti en 2003 sur Game Boy Advance.

Il a pour suite Summon Night: Swordcraft Story 2.', 'https://fr.wikipedia.org/wiki/Summon_Night:_Swordcraft_Story'),
  ('Q4672963', 'Ace Combat Advance est un jeu vidéo de type shoot ''em up développé Human Soft et édité par Namco sorti en 2006 sur Game Boy Advance. Ce fut le premier jeu de la série Ace Combat exclusivement sortie sur une console portable.', 'https://fr.wikipedia.org/wiki/Ace_Combat_Advance'),
  ('Q2256904', 'Dinotopia: The Timestone Pirates est un jeu vidéo d''action développé par RFX Interactive et édité par TDK Mediactive, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Dinotopia:_The_Timestone_Pirates'),
  ('Q5037208', 'Car Battler Joe est un jeu vidéo de type action-RPG et combat motorisé développé par Ancient et édité par Victor Interactive Software, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Car_Battler_Joe'),
  ('Q3312351', 'Super Mario Bros. 2 (ou Super Mario USA au Japon) est un jeu vidéo de plates-formes développé par Nintendo R&D4 et édité par Nintendo. Il sort sur Nintendo Entertainment System en 1988 en Amérique du Nord, en 1989 en Europe puis en 1992 au Japon.

Cet épisode n''est pas un jeu original puisqu''il s''agit de l''adaptation de Yume Kōjō: Doki Doki Panic, un jeu de Nintendo sorti au Japon sur Famicom Disk System en 1987. La première véritable suite à Super Mario Bros. est Super Mario Bros.: The Lost Levels (connu au Japon sous le nom de Super Mario Bros. 2) mais cet épisode n''étant pas sorti à l''époque en Occident, c''est cette adaptation qui a fait office de suite pour les Occidentaux.', 'https://fr.wikipedia.org/wiki/Super_Mario_Bros._2'),
  ('Q2564704', 'Kuru Kuru Kururin est un jeu vidéo d''action et de réflexion développé par Eighting et édité par Nintendo, sorti en 2001 sur Game Boy Advance au Japon et en Europe. C''est le premier jeu de la série Kururin. Il était disponible au lancement de la console.

Le joueur incarne Kururin, un oiseau qui pilote un hélicoptère, l''Helirin, à la recherche de ses frères et sœurs égarés. Il parcourt des niveaux dans lesquels il doit prendre garde à ne pas toucher les bords du chemin avec les pales de son hélice.

Il a reçu un bon accueil critique, s''est vendu à plus de 300 000 exemplaires au Japon, il a connu deux suites.', 'https://fr.wikipedia.org/wiki/Kuru_Kuru_Kururin'),
  ('Q3281078', 'Bienvenue chez les Robinson (Meet the Robinsons) est un jeu vidéo d''action-aventure et de réflexion développé par Avalanche Software, Buena Vista Games et Climax Studios et édité par Disney Interactive Studios, sorti en 2007 sur PlayStation 2, GameCube, Xbox 360, Wii, Windows, Game Boy Advance et Nintendo DS. Il est adapté du long métrage d''animation de Walt Disney Pictures Bienvenue chez les Robinson.', 'https://fr.wikipedia.org/wiki/Bienvenue_chez_les_Robinson_(jeu_vid%C3%A9o)'),
  ('Q4977851', 'Bruce Lee: Return of the Legend est un jeu vidéo de type beat them all développé par Vicarious Visions et édité par VU Games, sorti en 2003 sur Game Boy Advance. Le joueur y incarne Bruce Lee.', 'https://fr.wikipedia.org/wiki/Bruce_Lee:_Return_of_the_Legend'),
  ('Q4717686', 'Alex Rider: Stormbreaker est un jeu vidéo d''action développé par Altron et Razorback Developments, édité par THQ et sorti en 2006 sur Nintendo DS et Game Boy Advance. Il est adapté du film Stormbreaker lui-même tiré du roman même nom d''Anthony Horowitz.', 'https://fr.wikipedia.org/wiki/Alex_Rider:_Stormbreaker_(jeu_vid%C3%A9o)'),
  ('Q4839183', 'Back Track est un jeu vidéo de tir à la première personne développé et édité par Telegames, sorti en 1998 sur Windows et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Back_Track'),
  ('Q4743149', 'Super Black Bass Advance, titré American Bass Challenge en Amérique du Nord, est un jeu vidéo de pêche développé et édité par Starfish, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Super_Black_Bass_Advance'),
  ('Q2150454', 'Mario Tennis: Power Tour connu sous le nom de Mario Power Tennis en Europe est un jeu vidéo de tennis sorti en 2005 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Mario_Tennis:_Power_Tour'),
  ('Q4686065', 'Advance Guardian Heroes est un jeu vidéo de type beat them all développé par Treasure, sorti en 2004 sur Game Boy Advance. Il s''agit de la suite de Guardian Heroes sorti sur Sega Saturn en 1996.', 'https://fr.wikipedia.org/wiki/Advance_Guardian_Heroes'),
  ('Q2274675', 'Mushiking: King of the Beetles est un jeu vidéo de cartes à collectionner développé et édité par Sega, sorti en 2003 sur borne d''arcade, Game Boy Advance et Nintendo DS. Il met en scène des combats d''insectes.

Le jeu est inscrit au Livre Guinness des records pour le plus grand nombre de tournois organisés en salle d''arcade avec plus 100 000 tournois enregistrés en 2008.', 'https://fr.wikipedia.org/wiki/Mushiking:_The_King_of_Beetles'),
  ('Q4851779', 'Ballistic: Ecks vs. Sever II (Ballistic: Ecks vs. Sever en Amérique du Nord) est un jeu vidéo de tir à la première personne développé par Crawfish Interactive et édité par Bam! Entertainment, sorti en 2002 sur Game Boy Advance. Il est adapté sur le scénario final du film Ballistic, sorti la même année. Son prédécesseur, Ecks vs. Sever était basé sur une plus ancienne version du scénario et est sorti l''année précédente.', 'https://fr.wikipedia.org/wiki/Ballistic:_Ecks_vs._Sever_II'),
  ('Q4765050', 'Animaniacs: Lights, Camera, Action! est un jeu vidéo d''action développé par Warthog Games et édité par Ignition Entertainment, sorti en 2005 sur Game Boy Advance et Nintendo DS.', 'https://fr.wikipedia.org/wiki/Animaniacs:_Lights,_Camera,_Action!'),
  ('Q4386839', 'Dokapon: Monster Hunter est un jeu vidéo de type dungeon crawler développé et édité par Asmik Ace Entertainment, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Dokapon:_Monster_Hunter'),
  ('Q5011737', 'CIMA: The Enemy est un jeu vidéo de rôle développé par Neverland et édité par Marvelous Entertainment, sorti en 2003 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/CIMA:_The_Enemy'),
  ('Q2471393', 'Crash Bandicoot 2: N-Tranced est un jeu vidéo de plates-formes, développé par Vicarious Visions et édité par Vivendi Games, sorti sur Game Boy Advance le 7 janvier 2003 aux États-Unis. Il s’agit du second jeu de la série Crash Bandicoot à paraître sur console portable.', 'https://fr.wikipedia.org/wiki/Crash_Bandicoot_2:_N-Tranced'),
  ('Q167359', 'Pirates des Caraïbes: Le Secret du coffre maudit (Pirates of the Caribbean: Dead Man''s Chest) est un jeu vidéo d''action-aventure et de plates-formes édité et développé par Buena Vista Games. Il s''agit d''une adaptation du film du même nom réalisé par Gore Verbinski sorti en 2006.', 'https://fr.wikipedia.org/wiki/Pirates_des_Cara%C3%AFbes_:_Le_Secret_du_coffre_maudit_(jeu_vid%C3%A9o)'),
  ('Q3276921', 'Magical Vacation est un jeu vidéo de rôle développé par Brownie Brown et édité par Nintendo, sorti en 2001 sur Game Boy Advance. Il est réédité en 2015 sur la console virtuelle de la Wii U.

Il a pour suite Magical Starsign.', 'https://fr.wikipedia.org/wiki/Magical_Vacation'),
  ('Q2547348', 'Medal of Honor: Espionnage (Medal of Honor: Infiltrator) est un jeu vidéo de tir à la troisième personne développé par Netherock Ltd., et édité par Electronic Arts, sorti en 2003 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Medal_of_Honor_:_Espionnage'),
  ('Q5150224', 'Columns Crown est un jeu vidéo de puzzle développé par Wow Entertainment et édité par Sega, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Columns_Crown'),
  ('Q3284042', 'Ed, Edd n Eddy: Jawbreakers! est un jeu vidéo de plates-formes développé par Climax Group et édité par Bam! Entertainment, sorti en 2003 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Ed,_Edd_n_Eddy:_Jawbreakers!'),
  ('Q3285493', 'Rebelstar: Tactical Command est un jeu vidéo de type tactical RPG développé par Codo Technologies, sorti en 2005 sur Game Boy Advance.

Il fait suite à Rebelstar et Rebelstar II: Alien Encounter.', 'https://fr.wikipedia.org/wiki/Rebelstar:_Tactical_Command'),
  ('Q4787555', 'Arctic Tale est un jeu vidéo d''action-aventure développé par Atomic Planet Entertainment et édité par Zoo Digital Publishing, sorti en 2007 sur Wii, Game Boy Advance et Nintendo DS.

Il est adapté du film documentaire du même nom.', 'https://fr.wikipedia.org/wiki/Arctic_Tale_(jeu_vid%C3%A9o)'),
  ('Q2562228', 'Castlevania: Circle of the Moon, sorti en Europe simplement sous le nom Castlevania et au Japon sous le nom Akumajo Dracula: Circle of the Moon, est un jeu vidéo de type metroidvania développé et édité par Konami, sorti en 2001 sur Game Boy Advance. Il est le premier épisode de la série Castlevania sur Game Boy Advance et fait partie des jeux de lancement de la console. Connaissant un grand succès (un million d''exemplaires vendus moins d''un mois après sortie américaine et européenne), il est suivi par deux autres épisodes du même genre sur Game Boy Advance, Harmony of Dissonance en 2002 et Aria of Sorrow en 2003.', 'https://fr.wikipedia.org/wiki/Castlevania:_Circle_of_the_Moon'),
  ('Q5047407', 'Cartoon Network Speedway est un jeu vidéo de course développé par DC Studios et édité par Majesco Sales, sorti en 2003 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Cartoon_Network_Speedway'),
  ('Q5047405', 'Cartoon Network: Block Party est un jeu vidéo de type party game développé par One Man Band et édité par Majesco Entertainment, sorti en 2004 sur Game Boy Advance.

Il met en scène des personnages des séries Johnny Bravo, Ed, Edd et Eddy, Courage, le chien froussard et Cléo et Chico.', 'https://fr.wikipedia.org/wiki/Cartoon_Network:_Block_Party'),
  ('Q4749776', 'Fievel et le Trésor perdu (An American Tail: Fievel''s Gold Rush) est un jeu vidéo de plates-formes développé par Hokus Pokus et édité par Conspiracy Entertainment, sorti en 2002 sur Game Boy Advance.

S''il porte en version française le même nom que le long métrage d''animation Fievel et le Trésor perdu, il est pourtant adapté de la série d''animation Les Aventures de Fievel au Far West.', 'https://fr.wikipedia.org/wiki/Fievel_et_le_Tr%C3%A9sor_perdu_(jeu_vid%C3%A9o)'),
  ('Q4795646', 'Le Tour du monde en 80 jours (Around the World in 80 Days) est un jeu vidéo d''action-aventure développé par Saffire Corporation et édité par Thumbworks, édité par Hip Games, sorti en 2004 sur Game Boy Advance et téléphone mobile.

Il est basé sur le film du même nom sorti en 2004.', 'https://fr.wikipedia.org/wiki/Le_Tour_du_monde_en_80_jours_(jeu_vid%C3%A9o)'),
  ('Q2450773', 'Top Spin 2 est un jeu vidéo de tennis développé par PAM et sorti en 2006 sur Xbox 360, Windows (Steam), GBA et Nintendo DS.

Il s''agit de la suite du Top Spin, un jeu à succès en 2003 sur Xbox.', 'https://fr.wikipedia.org/wiki/Top_Spin_2'),
  ('Q3529558', 'Titi et les Bijoux magiques est un jeu vidéo party game développé par Kotobuki System et édité par Kemco, sorti en 2001 sur Game Boy Advance. Le jeu était disponible au lancement de la console.', 'https://fr.wikipedia.org/wiki/Titi_et_les_Bijoux_magiques'),
  ('Q1206503', 'Mario Party Advance est un party game comprenant 50 mini-jeux pour la Game Boy Advance créé par Nintendo, sorti le 13 janvier 2005 au Japon.', 'https://fr.wikipedia.org/wiki/Mario_Party_Advance'),
  ('Q3493436', 'Spider-Man: Mysterio''s Menace ou Spider-Man 3: Mysterio''s Menace est un jeu vidéo d''action-plates-formes développé par Vicarious Visions et édité par Activision en 2001 sur Game Boy Advance.

Comme son titre l''indique, il est proposé au joueur de vivre une aventure avec l''homme araignée provenant des Marvel Comics américains.

Il fait suite à Spider-Man et à la fois à Spider-Man 2: The Sinister Six sur Gameboy et Spider-Man 2: La Revanche d''Electro sur Playstation.', 'https://fr.wikipedia.org/wiki/Spider-Man:_Mysterio%27s_Menace'),
  ('Q3493448', 'Spider-Man: Bataille pour New York (Spider-Man: Battle for New York) est un jeu vidéo d''action-plates-formes développé par Torus Games et édité par Activision en 2006 sur Game Boy Advance et Nintendo DS. C''est un préquel du jeu sorti l''année précédente en 2005 Ultimate Spider-Man qui propose de vivre la première confrontation entre Spider-Man et le Bouffon Vert dans l''univers Ultimate, et explique pourquoi on retrouve le Bouffon prisonnier du SHIELD dans le premier jeu. Contrairement à ce dernier, il n''a été édité que sur consoles de jeu portables et pas sur PC ou consoles de salon.

Comme son titre l''indique, il est proposé au joueur de vivre une aventure avec l''homme araignée provenant des Marvel Comics américains.', 'https://fr.wikipedia.org/wiki/Spider-Man_:_Bataille_pour_New_York'),
  ('Q3224664', 'Le Monde de Nemo 2: L''Aventure continue (Finding Nemo: The Continuing Adventures) est un jeu vidéo d''action sorti en 2004 sur Game Boy Advance. Le jeu a été édité par THQ. Il est basé sur le film d''animation Le Monde de Nemo de Pixar.', 'https://fr.wikipedia.org/wiki/Le_Monde_de_Nemo_2_:_L%27Aventure_continue'),
  ('Q3120896', 'Gunstar Future Heroes (Gunstar Super Heroes au Japon et aux É.-U.) est un jeu vidéo développé par Treasure Co. Ltd et édité par Sega, sorti en 2005 sur Game Boy Advance. Il s''agit de la suite de Gunstar Heroes, sorti en 1993 sur Mega Drive.', 'https://fr.wikipedia.org/wiki/Gunstar_Future_Heroes'),
  ('Q3573068', 'Yu-Gi-Oh! Reshef le Destructeur est un jeu vidéo sorti sur Game Boy Advance en septembre 2004.

Le jeu était vendu avec trois cartes à jouer (Grandmoth Ultimement Parfait, Riryoku et Annulation d''attaque) du jeu de cartes à collectionner Yu-Gi-Oh! Jeu de cartes à jouer.

Le jeu est sorti en Double Pack avec Yu-Gi-Oh! Les Cartes sacrées.', 'https://fr.wikipedia.org/wiki/Yu-Gi-Oh!_Reshef_le_Destructeur'),
  ('Q3573062', 'Yu-Gi-Oh! Les Cartes sacrées (Yu-Gi-Oh! The Sacred Cards) est un jeu vidéo sorti sur Game Boy Advance en janvier 2004. C''est la première aventure avec un mode histoire de Yu-Gi-Oh! sur console portable.

Le jeu était vendu avec trois cartes à jouer (Échange, Dé gracieux et Dé crâne) du jeu de cartes à collectionner Yu-Gi-Oh! Jeu de cartes à jouer..

Le jeu est sorti en Double Pack avec Yu-Gi-Oh! Reshef le Destructeur.', 'https://fr.wikipedia.org/wiki/Yu-Gi-Oh!_Les_Cartes_sacr%C3%A9es'),
  ('Q3504171', 'Super Dodge Ball Advance (Bakunetsu Dodge Ball Fighters en version originale japonaise) est un jeu vidéo de sport développé par Atlus, sorti en 2001 sur Game Boy Advance. Il s''agit d''une adaptation du jeu Super Dodge Ball sur Super Nintendo. Il était disponible au lancement de la console aux États-Unis et au Japon.', 'https://fr.wikipedia.org/wiki/Super_Dodge_Ball_Advance'),
  ('Q3504715', 'Superman: Countdown to Apokolips est un jeu vidéo d''action sorti en 2003 sur Game Boy Advance. Le jeu a été développé par Mistic Software et édité par Atari Inc.. Le jeu est adapté de la série d''animation Superman, l''Ange de Metropolis. Aussi, Countdown sert de préquelle au jeu Superman: Shadow of Apokolips.

Le jeu est sorti le 26 mars 2003 en Amérique du Nord et le 25 avril 2003 en Europe.', 'https://fr.wikipedia.org/wiki/Superman:_Countdown_to_Apokolips'),
  ('Q3226597', 'Le Roi lion, également appelé The Lion King 1½ en Amérique du Nord, est un jeu vidéo de plates-formes développé par Vicarious Visions et édité par THQ et Disney Interactive sur Game Boy Advance en 2003.

Le jeu suit la trame du film Le Roi lion 3: Hakuna Matata.', 'https://fr.wikipedia.org/wiki/Le_Roi_lion_(jeu_vid%C3%A9o,_2003)'),
  ('Q3271697', 'Boktai 3: Sabata''s Counterattack est un jeu vidéo de type action-RPG développé et édité par l''entreprise japonaise Konami. Il sort sur Game Boy Advance en 2005. Cet opus n''est pas sorti en dehors du Japon.', 'https://fr.wikipedia.org/wiki/Boktai_3:_Sabata%27s_Counterattack'),
  ('Q3072358', 'Final Fantasy I and II: Dawn of Souls est une réédition sur Game Boy Advance des deux premiers jeux vidéo de la série Final Fantasy (Final Fantasy I et Final Fantasy II), initialement sorti sur Nintendo Entertainment System. Sortie au Japon sous le nom de Final Fantasy I + II Advance, elle est globalement similaire à la précédente réédition sur PlayStation, Final Fantasy I and II: Premium Package.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_I_and_II:_Dawn_of_Souls'),
  ('Q3062930', 'F-Zero: Climax est un jeu vidéo de course futuriste sorti sur Game Boy Advance en 2004, développé par Suzak et édité par Nintendo. Sorti le 21 octobre 2004 et uniquement au Japon, c''est le troisième opus de la série des F-Zero sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/F-Zero:_Climax'),
  ('Q3546915', 'Justice League: Injustice for All est un jeu vidéo d''action développé par Saffire et édité par Midway Games, sorti en 2002 sur Game Boy Advance.

Le design graphique du jeu est basé sur celui de la série animée La Ligue des justiciers.

Il a pour suite Justice League: Chronicles.', 'https://fr.wikipedia.org/wiki/Justice_League:_Injustice_for_All'),
  ('Q3154354', 'Iridion II est un shoot them up développé par Shin''en et édité par Majesco, sorti en 2003 sur Game Boy Advance. Il est la suite d''Iridion 3D. Il délaisse le shoot 3D pour être un shoot them up à défilement vertical classique.', 'https://fr.wikipedia.org/wiki/Iridion_II'),
  ('Q3482234', 'Shining Soul est un action RPG sorti sur Game Boy Advance, développé par Nex Entertainment et Grasshopper Manufacture, et édité par Sega. Ce jeu fait partie de la série Shining.

Il est possible d''incarner quatre types de classes: archer, guerrier, magicien et dragonien. Le principe du jeu est basé sur le Porte-monstre-trésor.', 'https://fr.wikipedia.org/wiki/Shining_Soul'),
  ('Q3497066', 'Star X est un rail shooter développé par Graphic State et édité par Bam! Entertainment, sorti en 2002 sur Game Boy Advance. Il comprend également des phases de combat spatial en arène.', 'https://fr.wikipedia.org/wiki/Star_X'),
  ('Q3072788', 'Fire Emblem: The Binding Blade est un jeu vidéo de rôle tactique sorti sur Game Boy Advance en 2002, développé par Intelligent Systems et publié par Nintendo uniquement au Japon. Il s''agit du sixième jeu de la série Fire Emblem et le premier sur Game Boy Advance, marquant l''arrivée de la franchise sur console portable.

Chronologiquement, Fire Emblem: The Binding Blade est la suite de Fire Emblem: The Blazing Blade bien qu''il soit sorti avant. Il met en vedette Roy, le fils d''Eliwood, qui doit diriger un groupe de combattants destiné à vaincre les troupes du roi de Biran. De nombreux personnages jouables sont par ailleurs les enfants des personnages de Fire Emblem: The Blazing Blade, et certains sont même jouables dans les deux opus.', 'https://fr.wikipedia.org/wiki/Fire_Emblem:_The_Binding_Blade'),
  ('Q3108764', 'Rhythm Tengoku est un jeu de rythme (jeu d''action basé sur le rythme) développé par Nintendo R&D1. Il est sorti au Japon le 3 août 2006, et a été le dernier jeu développé par Nintendo sur Game Boy Advance. Le jeu a reçu un prix d''Excellence catégorie Divertissement lors du 10e Japan Media Arts Festival en 2006.', 'https://fr.wikipedia.org/wiki/Rhythm_Tengoku'),
  ('Q1195267', 'WarioWare, Inc.: Mega Mini-Jeux, en anglais WarioWare, Inc.: Minigame Mania, connu sous le nom de Made in Wario au Japon et de WarioWare, Inc.: Mega Microgame$! en Amérique du Nord, est un jeu vidéo développé et édité par Nintendo et commercialisé sur Game Boy Advance, GameCube et Nintendo 3DS. Il met en scène Wario, créant son entreprise de jeu vidéo et demandant à quelques-uns de ses amis de l''aider à concevoir des jeux. Le rôle du joueur étant de tester lesdits jeux vidéo.', 'https://fr.wikipedia.org/wiki/WarioWare,_Inc._:_Mega_Mini-Jeux'),
  ('Q3120980', 'Guru Logi Champ est un jeu vidéo de puzzle sorti en 2001 sur Game Boy Advance. Le jeu a été développé et édité par Compile.', 'https://fr.wikipedia.org/wiki/Guru_Logi_Champ'),
  ('Q3482233', 'Shining Soul II est un action RPG sorti sur Game Boy Advance, développé par Nex Entertainment et Grasshopper Manufacture, et édité par Sega. Ce jeu fait partie de la série Shining.

Le titre est la suite de Shining Soul sorti sur la même console en 2002.', 'https://fr.wikipedia.org/wiki/Shining_Soul_II'),
  ('Q3483555', 'Sigma Star Saga est un jeu vidéo développé par WayForward Technologies et publié par Namco sur Game Boy Advance en 2005.', 'https://fr.wikipedia.org/wiki/Sigma_Star_Saga'),
  ('Q3532027', 'Top Gear GT Championship (Zen-Nippon GT Senshuken ou All Japan GT Championship en version originale japonaise) est un jeu vidéo de course développé par Vision Works et édité par Kemco, sorti en 2001 sur Game Boy Advance. Il fait partie de la série Top Gear. Il s''agit du premier de celle-ci sur Game Boy Advance et était disponible au lancement de la console.', 'https://fr.wikipedia.org/wiki/Top_Gear_GT_Championship'),
  ('Q3546928', 'Justice League: Chronicles est un jeu vidéo d''action développé par Full Fat et édité par Midway Games, sorti en 2003 sur Game Boy Advance.

Le design graphique du jeu est basé sur celui de la série animée La Ligue des justiciers.

Il fait suite à Justice League: Injustice for All.', 'https://fr.wikipedia.org/wiki/Justice_League:_Chronicles'),
  ('Q3573059', 'Yu-Gi-Oh! Dungeondice Monsters est un jeu vidéo de type tactical RPG développé et édité par Konami, sorti à partir de 2001 sur Game Boy Advance. Il s''agit du premier jeu de la licence Yu-Gi-Oh! sur cette console et était disponible au lancement de celle-ci au Japon. Il reprend le principe du jeu de plateau Dungeondice Monsters de la deuxième série d''anime et du manga.', 'https://fr.wikipedia.org/wiki/Yu-Gi-Oh!_Dungeondice_Monsters'),
  ('Q1368157', 'WarioWare: Twisted! est un jeu vidéo sorti sur Game Boy Advance en Amérique du Nord et au Japon, le jeu n''est toutefois pas commercialisé en Europe. Comme les autres WarioWare, ce jeu est un enchaînement aléatoire de micro-jeux ne durant pas plus de quelques secondes. La principale nouveauté de cet opus est la présence d''un capteur d''inclinaison dans la cartouche du jeu. Le joueur doit bouger la console pour jouer à ces micro-jeux. Certains micro-jeux utilisent le mouvement et la pression du bouton A et le jeu de Kat & Ana n''utilise que le bouton A.

Il est l''un des deux jeux à utiliser une cartouche dotée d''une technologie vibrante avec Drill Dozer.', 'https://fr.wikipedia.org/wiki/WarioWare:_Twisted!'),
  ('Q2421937', 'Mega Man Zero 4 (Rockman Zero 4 au Japon) est un action-plates-formes développé par Inti Creates et édité par Capcom en 2005 sur Game Boy Advance. Il fait partie de la franchise Mega Man et est le quatrième de la série dérivée Mega Man Zero. Il est réédité dans la compilation Mega Man Zero Collection sur Nintendo DS en 2010 et sur la console virtuelle de la Wii U en 2015.', 'https://fr.wikipedia.org/wiki/Mega_Man_Zero_4'),
  ('Q1754203', 'Boktai: The Sun is in Your Hand est un jeu vidéo de type action-RPG développé et édité par l''entreprise japonaise Konami. Il sort sur Game Boy Advance en 2003. Il est remarqué pour un gameplay entièrement nouveau basé sur le soleil: la cartouche est équipée d''un capteur solaire afin de modifier l''expérience vécue par le joueur. Le nom du jeu est la contraction du japonais Bokura no Taiyô qui veut dire « notre soleil ».', 'https://fr.wikipedia.org/wiki/Boktai:_The_Sun_Is_in_Your_Hand'),
  ('Q5219604', 'F-Zero: GP Legend est un jeu vidéo de course futuriste sorti sur Game Boy Advance en 2003, développé par Suzak Inc. et édité par Nintendo.', 'https://fr.wikipedia.org/wiki/F-Zero:_GP_Legend'),
  ('Q1358804', 'The Legend of Zelda: A Link to the Past / Four Swords (ou simplement A Link to the Past et Four Swords) est un jeu vidéo d''action-aventure développé par Flagship, sous la supervision de Nintendo et édité par ce dernier sur Game Boy Advance en 2002. C''est la réédition sur portable du jeu A Link to the Past sorti en 1991 sur Super Nintendo et le neuvième jeu de la série The Legend of Zelda. La cartouche comporte un second jeu inédit de l''univers Zelda uniquement multijoueur en réseau local, intitulé The Legend of Zelda: Four Swords.

A Link to the Past se déroule dans un univers d''heroic fantasy affiché en vue de dessus dans lequel le joueur dirige un personnage. Link combat Agahnim, Ganon, puis délivre la princesse Zelda et obtient la Triforce. Depuis sa sortie en 1991, le jeu est considéré comme l''un des meilleurs jeux de la série Zelda et de tous les temps. Ce portage au pixel près ne comporte que de très légères modifications de son gameplay. Le jeu propose un niveau et une quête secondaire supplémentaires, et la bande-son a été remaniée, Link pouvant pousser des cris, repris du jeu d''Ocarina of Time.', 'https://fr.wikipedia.org/wiki/The_Legend_of_Zelda:_A_Link_to_the_Past_/_Four_Swords'),
  ('Q5196402', 'Custom Robo GX est un jeu vidéo de type action-RPG développé par Noise et édité par Nintendo, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Custom_Robo_GX'),
  ('Q2383167', 'Mother 3 est un jeu vidéo de rôle (RPG) développé par Brownie Brown et HAL Laboratory, et édité par Nintendo pour sa console portable la Game Boy Advance, dont l’essence trouve son origine dans l’esprit de Shigesato Itoi. Après un développement chaotique de presque 10 ans, le jeu est sorti au Japon le 20 avril 2006. Il s’agit du troisième épisode de la trilogie Mother.

Mother 3 a obtenu un 35/40 dans Famitsu. Il est souvent reconnu comme le meilleur épisode de la série Mother.

400 000 exemplaires de Mother 3 avaient été écoulés au Japon en septembre 2006.

Le jeu sort sur la console virtuelle de la Wii U le 17 décembre 2015 au Japon.', 'https://fr.wikipedia.org/wiki/Mother_3'),
  ('Q2311359', 'X-Men: Reign of Apocalypse est un jeu vidéo de type beat them all pour la console Game Boy Advance qui met en vedette les personnages du comics des X-Men. Le jeu a été développé par Digital Eclipse et a été édité par Activision en 2001.', 'https://fr.wikipedia.org/wiki/X-Men:_Reign_of_Apocalypse'),
  ('Q1754927', 'Sega Rally Championship est un jeu vidéo de course développé par Sega AM5 et édité par Sega sur borne d''arcade en 1994. Le jeu a été porté sur Saturn (1995, Sega AM3), PC (1997), Game Boy Advance (2002) et N-Gage (2004).

Sega Rally Championship est le plus gros succès commercial de Sega en salle d''arcade. Le jeu est encore proposé dans certaines salles quinze ans après sa sortie initiale.', 'https://fr.wikipedia.org/wiki/Sega_Rally_Championship'),
  ('Q2446730', 'Garfield: À la recherche de Pooky (Garfield: The Search for Pooky) est un jeu vidéo d''action développé par InterActive Vision édité par The Game Factory, sorti en 2004 sur Game Boy Advance. Il faut chercher Pooky, le nounours de Garfield, qui a été volé par trois rats en traversant tous les niveaux.', 'https://fr.wikipedia.org/wiki/Garfield_:_%C3%80_la_recherche_de_Pooky'),
  ('Q5223138', 'Dark Arena est un jeu vidéo de tir à la première personne développé par Graphic State, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Dark_Arena'),
  ('Q5229397', 'Dave Mirra Freestyle BMX 3 est un jeu vidéo de sport (BMX) développé par Full Fat édité par AKA Acclaim, sorti en 2002 sur Game Boy Advance. Il s''agit de la suite de Dave Mirra Freestyle BMX et de Dave Mirra Freestyle BMX 2.

Le joueur peut y incarner différents cyclistes BMX professionnels dont Dave Mirra.', 'https://fr.wikipedia.org/wiki/Dave_Mirra_Freestyle_BMX_3'),
  ('Q2333614', 'Tekken Advance est un jeu vidéo de combat, développé et édité par Namco, sorti en 2001 sur Game Boy Advance. Il fait partie de la série des Tekken. C''est le premier jeu de la série à sortir tant sur une console portable que sur une console qui n''est pas de marque Sony — Nintendo en l''occurrence. Il s''agit d''une adaptation de Tekken 3, mais elle comporte moins de personnages et aucun mode « Histoire ».', 'https://fr.wikipedia.org/wiki/Tekken_Advance'),
  ('Q5220738', 'Danny Fantôme: La Jungle urbaine (Danny Phantom: Urban Jungle) est un jeu vidéo d''action développé par Altron édité par THQ, sorti en 2006 sur Game Boy Advance et Nintendo DS. Il est basé sur la série d''animation Danny Fantôme.', 'https://fr.wikipedia.org/wiki/Danny_Fant%C3%B4me_:_La_Jungle_urbaine'),
  ('Q5220737', 'Danny Fantôme: L''Ultime Ennemi (Danny Phantom: The Ultimate Enemy) est un jeu vidéo d''action développé par Altron édité par THQ, sorti en 2005 sur Game Boy Advance. Il est basé sur la série d''animation Danny Fantôme.', 'https://fr.wikipedia.org/wiki/Danny_Fant%C3%B4me_:_L%27Ultime_Ennemi'),
  ('Q1320023', 'Yu-Gi-Oh! Worldwide Edition: Stairway to the Destined Duel est le premier jeu vidéo de cartes de combat Yu-Gi-Oh! à sortir sur Game Boy Advance en France.

Il s''agissait du jeu électronique officiel pour le tournoi mondial 2003.

On y retrouve les duellistes de la première série télévisée Yu-Gi-Oh!, l''histoire prenant place à Battle City. On peut collecter jusqu''à 1 050 cartes du jeu de cartes à collectionner Yu-Gi-Oh! Jeu de cartes à jouer, par contre le programme ne garde en mémoire qu''un deck à la fois, il faut donc noter où se souvenir de tel ou tel deck selon sa stratégie.

Les déplacements entre les duels se font sur une carte de case en case, de nouveaux adversaires apparaissent en fonction du nombre de victoires, et des concours sont lancés tous les 7 jour/tour ou 30 jour/tour (analogie entre le déplacement à la suite d''un tour et le déroulement d''une journée).', 'https://fr.wikipedia.org/wiki/Yu-Gi-Oh!_Worldwide_Edition:_Stairway_to_the_Destined_Duel'),
  ('Q1322480', 'Phoenix Wright: Ace Attorney est un jeu vidéo développé et édité par l''entreprise japonaise Capcom. Il est d''abord sorti sur Game Boy Advance en 2001 au Japon. Le jeu est porté sur Nintendo DS en 2005 au Japon puis en 2006 en Occident. Malgré la construction assez inhabituelle du jeu pour l''Occident, cette version rencontre un succès critique et commercial.

Le joueur y incarne un avocat débutant, Phoenix Wright, au cours de quatre affaires, dans lesquelles il devra prouver l''innocence de ses clients à force de preuves et de contre-interrogatoires. La version Nintendo DS ajoute un cinquième chapitre.', 'https://fr.wikipedia.org/wiki/Phoenix_Wright:_Ace_Attorney'),
  ('Q2588758', 'Sword of Mana est un jeu vidéo de type action-RPG développé par le studio tokyoite Brownie Brown pour les éditeurs Square Enix et Nintendo. Il s''agit d''un remake de Mystic Quest, le premier jeu de la série Seiken Densetsu ou Mana. Le jeu est édité sur Game Boy Advance en 2003 au Japon et aux États-Unis puis en 2004 en Europe.', 'https://fr.wikipedia.org/wiki/Sword_of_Mana'),
  ('Q4866426', 'Baseball Advance (Greatest Nine au Japon) est un jeu vidéo de sport (baseball) développé par Smilebit, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Baseball_Advance'),
  ('Q4869949', 'BattleBots: Beyond the BattleBox est un jeu vidéo d''action fondé sur la licence BattleBots développé par Cave+Barn Studios et Pipe Dream Interactive, édité par Majesco Entertainment. Il est sorti en 2002 sur Game Boy Advance.

Il a pour suite BattleBots: Design and Destroy.', 'https://fr.wikipedia.org/wiki/BattleBots:_Beyond_the_BattleBox'),
  ('Q4915187', 'Bionicle: Matoran Adventures est un jeu vidéo d''action-aventure développé par Argonaut Games et édité par Electronic Arts, sorti en 2001 sur Game Boy Advance.

Il est basé sur la gamme de jouets du même nom.', 'https://fr.wikipedia.org/wiki/Bionicle:_Matoran_Adventures'),
  ('Q4915188', 'Bionicle: Maze of Shadows est un jeu vidéo d''action-aventure développé par Razorback Developments et édité par THQ, sorti en 2005 sur Game Boy Advance.

Il est basé sur la gamme de jouets du même nom.', 'https://fr.wikipedia.org/wiki/Bionicle:_Maze_of_Shadows'),
  ('Q4943317', 'Bookworm est un jeu vidéo de réflexion développé et édité par PopCap Games, sorti en 2003 sur Windows, Mac OS, iOS, Game Boy Advance, Xbox Live Arcade, J2ME, BREW, Palm OS, Nintendo DS et DSiWare.', 'https://fr.wikipedia.org/wiki/Bookworm'),
  ('Q2712105', 'Bomberman Tournament est un jeu vidéo de réflexion et de rôle développé par Hudson Soft sur Game Boy Advance en 2001. Il s''inscrit dans la série Bomberman en proposant le mode de jeu classique ainsi qu''un mode aventure en solo.', 'https://fr.wikipedia.org/wiki/Bomberman_Tournament'),
  ('Q2705679', 'Dragon Ball Z: L’Héritage de Goku (Dragon Ball Z: The Legacy of Goku) est un jeu vidéo d’action-RPG édité par Infogrames et développé par Webfoot Technologies sur l''univers de Dragon Ball Z. Le jeu est disponible depuis 2002 sur Game Boy Advance.

C’est le premier volet de la série L’Héritage de Goku.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z_:_L%27H%C3%A9ritage_de_Goku'),
  ('Q2609107', 'Mega Man Battle Network est un tactical RPG développé par Capcom Production Studio 2 et édité par Capcom en 2001 sur Game Boy Advance. C''est le premier jeu de la série Mega Man Battle Network. Il est réédité en 2014 sur la console virtuelle de la Wii U.', 'https://fr.wikipedia.org/wiki/Mega_Man_Battle_Network_(jeu_vid%C3%A9o)'),
  ('Q2712511', 'Digimon Racing est un jeu vidéo de course, développé par Griptonite Games et distribué par Bandai, publié en 2004 sur Game Boy Advance. Partie intégrante de la série des jeux vidéo Digimon, ce jeu met en avant les éléments et les personnages de la franchise japonaise éponyme. Le système de jeu ressemble au plus haut point à celui d''un jeu de course classique, qui utilise à la fois les éléments du karting et des jeux d''action. Au total, onze personnages et 40 digivolutions sont disponibles.

Digimon Racing utilise le mode 7 et le doublage durant les courses. Le jeu a, pour la première fois, été annoncé à l’Electronic Entertainment Expo (E3) en 2003 et, plus tard, exposé à l’E3 de 2004. Il est publié le 1er avril 2004 au Japon; le 13 septembre en Amérique du Nord et le 30 avril en Europe, notamment le 23 avril en France. Le système de jeu est principalement bien accueilli par l''ensemble de la presse spécialisée, malgré sa ressemblance avec le système de jeu des séries Crash Nitro Kart et Mario Kart.', 'https://fr.wikipedia.org/wiki/Digimon_Racing'),
  ('Q5307541', 'Drill Dozer, connu sous le nom de Screw Breaker Gōshin Drillero au Japon, est un jeu vidéo d''action développé par Game Freak et édité par Nintendo, sorti en 2005 au Japon et en 2006 en Amérique du Nord sur Game Boy Advance.

Il est l''un des deux jeux à utiliser une cartouche dotée d''une technologie vibrante avec WarioWare: Twisted!.', 'https://fr.wikipedia.org/wiki/Drill_Dozer'),
  ('Q5472711', 'Fortress est un jeu vidéo de réflexion et stratégie en temps réel, assimilable au genre du tower defense, développé par Pipe Dream Interactive et édité par Majesco Entertainment, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Fortress_(jeu_vid%C3%A9o,_2001)'),
  ('Q2698085', 'Castlevania: Harmony of Dissonance, connu au Japon sous le titre Castlevania: Byakuya no Concerto, est un jeu vidéo de type metroidvania publié en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Castlevania:_Harmony_of_Dissonance'),
  ('Q5324241', 'ESPN Final Round Golf (ou ESPN Final Round Golf 2002 aux États-Unis) est un jeu vidéo de sport (golf) développé et édité par Konami, sorti en 2001 sur Game Boy Advance. Il était disponible au lancement de la console. La version occidentale présente quelques adaptations par rapport à la version originale japonaise intitulée JGTO Kōnin Golf Master: Japan Golf Tour Game.', 'https://fr.wikipedia.org/wiki/ESPN_Final_Round_Golf'),
  ('Q2617932', 'Duke Nukem Advance est un jeu de tir à la première personne de la série Duke Nukem, développé par Torus Games pour la Game Boy Advance. Le jeu est sorti le 12 aout 2002 aux États-Unis et le 20 septembre 2002 en Europe.', 'https://fr.wikipedia.org/wiki/Duke_Nukem_Advance'),
  ('Q5451412', 'Fire Pro Wrestling 2 est un jeu vidéo de catch développé par Spike et édité par Bam! Entertainment, sorti en 2002 sur Game Boy Advance. Il fait suite à Fire Pro Wrestling.', 'https://fr.wikipedia.org/wiki/Fire_Pro_Wrestling_2'),
  ('Q477882', 'Wing Commander: Prophecy est un jeu vidéo de combat spatial développé par les studios d''Origin Systems, sorti en 1997 sur PC puis réédité en 2003 sur Game Boy Advance. Cet opus est la suite directe du quatrième volet de la série Wing Commander, et donc considéré comme le cinquième de la saga. Il mêle séquences de shoot spatial et d''aventure, via des déplacements dans un vaisseau-mère, et dispose de nombreuses cinématiques filmées.

Une extension pouvant fonctionner seule, Secret Operations, a été éditée par Origin en 1998. Fait remarquable, il a été disponible uniquement sur Internet et gratuitement, bien que la taille initiale du fichier rendait sont téléchargement presque impossible pour les connexions modem de l''époque.', 'https://fr.wikipedia.org/wiki/Wing_Commander:_Prophecy'),
  ('Q2625613', 'Shrek le troisième (Shrek the Third) est un jeu vidéo d''action-aventure développé par 7 Studios et Shaba Games, édité par Activision, sorti en 2007 sur Windows, Wii, PlayStation 2, Xbox 360, Game Boy Advance, Nintendo DS, PlayStation Portable et J2ME.

Il est basé sur le film du même nom, faisant suite aux deux premiers films, eux-mêmes adaptés en jeux vidéo.', 'https://fr.wikipedia.org/wiki/Shrek_le_troisi%C3%A8me_(jeu_vid%C3%A9o)'),
  ('Q2045645', 'Pokémon version Émeraude est un jeu vidéo complémentaire à Pokémon Rubis et Saphir, appartenant à la série de jeux Pokémon. Il est sorti sur GBA au Japon le 16 septembre 2004, le 30 avril 2005 en Amérique du Nord, le 9 juin 2005 en Australie et le 21 octobre 2005 en Europe, après Pokémon Rouge Feu et Vert Feuille.

Pokémon Émeraude est l''amélioration graphique de Pokémon Rubis et Saphir sur Game Boy Advance. Certaines espèces complémentaires aux autres versions, ainsi que quelques nouveautés comme la possibilité de capturer Groudon en même temps que Kyogre ou après la Ligue, d''avoir le choix entre Latias et Latios, l''animation des Pokémon au début du combat, ou encore l''ajout de la Zone de combat (Battle Frontier) ont été rajoutées au jeu initial. Le Pokémon mascotte du jeu est Rayquaza.', 'https://fr.wikipedia.org/wiki/Pok%C3%A9mon_%C3%89meraude'),
  ('Q610923', 'Sonic Battle est un jeu vidéo de combat développé par Sonic Team et édité par Sega, mettant en scène Sonic et ses amis. L''intrigue tourne autour d''un robot abandonné par Eggman puis découvert sur la plage d''Emerald Beach par Sonic et baptisé Emerl, car pouvant assimiler les émeraudes du chaos pour devenir plus fort et plus intelligent. Emerl peut améliorer ses capacités en apprenant de nouvelles techniques au combat, un système de cartes apparaissant à la fin de chaque match en mode story. La programmation d''Emerl est d''ailleurs mise à contribution par le joueur pour développer sa stratégie.

Le jeu en lui-même est réalisé avec des décors tournant dans des arènes en 3D. Chaque début de match et chaque reprise après un K-O est suivi du choix de l''ordre de l''attaque spéciale (3 combinaisons), le bouton L permettant de récupérer de l''énergie et aussi de gonfler une jauge. Si cette dernière est pleine lors de l''exécution d''un coup spécial, cela peut mettre automatiquement K-O un adversaire.', 'https://fr.wikipedia.org/wiki/Sonic_Battle'),
  ('Q602642', 'Banjo-Pilot (à l''origine Diddy Kong Pilot) est un jeu vidéo de course développé par Rare et édité par THQ. Il est sorti en 2005 sur Game Boy Advance. Le jeu met en scène des personnages et des environnements issus de la série de jeux Banjo-Kazooie.', 'https://fr.wikipedia.org/wiki/Banjo-Pilot'),
  ('Q4116496', 'L''Âge de glace (Ice Age) est un jeu vidéo de plates-formes développé par Artificial Mind and Movement et édité par Ubisoft, sorti en 2002 sur Game Boy Advance. Il est adapté du long métrage d''animation L''Âge de glace.', 'https://fr.wikipedia.org/wiki/L%27%C3%82ge_de_glace_(jeu_vid%C3%A9o)'),
  ('Q1527204', 'Army Men Advance est un jeu vidéo d''action développé par DC Studios et édité par The 3DO Company, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Army_Men_Advance'),
  ('Q1527222', 'Army Men: Operation Green est un jeu vidéo d''action développé par Pocket Studios et édité par The 3DO Company, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Army_Men:_Operation_Green'),
  ('Q4050406', 'Super Monkey Ball Jr. est un jeu vidéo de plates-formes développé par Realism Ltd et édité par THQ et Sega. Il est sorti en 2002 sur Game Boy Advance. Le jeu a été porté sur N-Gage sous le nom de Super Monkey Ball.', 'https://fr.wikipedia.org/wiki/Super_Monkey_Ball_Jr.'),
  ('Q2019488', 'Tales of the World: Narikiri Dungeon 3 est un spin-off (comprenez: jeu issu d''une série parallèle à la série principale) de la série de jeux vidéo de rôle Tales of, éditée par Namco. Ce jeu n''est parut qu''au Japon sur Game Boy Advance le 6 janvier 2005. Il s''agit d''une suite à son prédécesseur sorti en 2002, Tales of the World: Narikiri Dungeon 2.', 'https://fr.wikipedia.org/wiki/Tales_of_the_World:_Narikiri_Dungeon_3'),
  ('Q2038683', 'Crazy Taxi: Catch a Ride est un épisode de la série Crazy Taxi sorti exclusivement sur Game Boy Advance en 2003. Le jeu est développé par Graphic State Games et édité par THQ.', 'https://fr.wikipedia.org/wiki/Crazy_Taxi:_Catch_a_Ride'),
  ('Q4051516', 'Tiny Toon Adventures: Buster''s Bad Dream est un jeu vidéo d''action mettant en scène les personnages des Tiny Toons, série d''animation apparue sur télévision en 1990. Le jeu fut développé par Treasure pour la Game Boy Advance en 2002.', 'https://fr.wikipedia.org/wiki/Tiny_Toon_Adventures:_Buster%27s_Bad_Dream'),
  ('Q6314922', 'Jurassic Park III: Dino Attack (Jurassic Park III: Advanced Action au Japon, Jurassic Park III: Island Attack en Amérique du Nord, également connu sous son nom de projet Jurassic Park III: Primal Fear) est un jeu vidéo d''action-aventure développé par Mobile21 et édité par Konami, sorti en 2001 sur Game Boy Advance. Il est adapté du film Jurassic Park III.', 'https://fr.wikipedia.org/wiki/Jurassic_Park_3:_Dino_Attack'),
  ('Q6902814', 'Monster Rancher Advance 2, aussi connu sous le nom de Monster Farm Advance 2 au Japon, est un jeu vidéo Game Boy Advance issu de la série de jeux vidéo Monster Rancher, publié en 2002.', 'https://fr.wikipedia.org/wiki/Monster_Rancher_Advance_2'),
  ('Q3714563', 'Double Dragon est un jeu vidéo de type beat them all développé par Technos, sorti sur borne d''arcade en 1987, et adapté sur divers consoles et ordinateurs de l''époque.

Il s''agit du premier épisode de la série Double Dragon.

Également développé par Yoshihisa Kishimoto, il est considéré comme le successeur spirituel de Renegade (1986).

La version NES de ce jeu a la particularité d''être sortie en France après sa suite Double Dragon II: The Revenge.', 'https://fr.wikipedia.org/wiki/Double_Dragon_(jeu_vid%C3%A9o,_1987)'),
  ('Q6168261', 'Jazz Jackrabbit est un jeu vidéo de plates-formes développé par Game Titan et édité par Jaleco, sorti en 2002 sur Game Boy Advance.

Il s''agit d''une suite aux jeux Jazz Jackrabbit, Jazz Jackrabbit 2 et Jazz Jackrabbit 3', 'https://fr.wikipedia.org/wiki/Jazz_Jackrabbit_(jeu_vid%C3%A9o,_2002)'),
  ('Q1839174', 'Sonic Pinball Party est un jeu vidéo de flipper sorti en 2003 sur Game Boy Advance. Le jeu a été développé par la Sonic Team puis édité par Sega.', 'https://fr.wikipedia.org/wiki/Sonic_Pinball_Party'),
  ('Q6703677', 'Lunar Legend est un jeu vidéo de rôle développé par Japan Art Media, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Lunar_Legend'),
  ('Q6699626', 'Lufia: The Ruins of Lore est un jeu vidéo de rôle développé par Atelier Double, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Lufia:_The_Ruins_of_Lore'),
  ('Q6798460', 'Mazes of Fate est un jeu vidéo de type dungeon crawler développé par Sabarasa, sorti en 2006 sur Game Boy Advance et Nintendo DS.', 'https://fr.wikipedia.org/wiki/Mazes_of_Fate'),
  ('Q1797550', 'Mario and Luigi: Superstar Saga est un jeu vidéo de rôle (ou plus couramment "RPG", de l''anglais "Role Playing Game") édité par Nintendo pour sa console portable Game Boy Advance en 2003. Le jeu est développé par le studio AlphaDream. Il s''agit du troisième jeu mettant en scène Mario dans un RPG après Super Mario RPG: Legend of the Seven Stars (SNES/SFC) et Paper Mario (N64), ainsi que le premier de la série Mario & Luigi. Le jeu s''est vendu à 2,17 millions d''exemplaires.

Un remake intitulé Mario and Luigi: Superstar Saga + Bowser''s Minions est sorti sur Nintendo 3DS le 6 octobre 2017. L''histoire est inchangée, mais les graphismes ont été refaits pour la console, auquel a été ajouté le mode de jeu "Super Sbires Saga", racontant ce qui arrive aux sbires de Bowser après l''écrasement du Tortue-Jet.', 'https://fr.wikipedia.org/wiki/Mario_and_Luigi:_Superstar_Saga'),
  ('Q6038366', 'Inspector Gadget: Advance Mission est un jeu vidéo de plates-formes développé par Magic Pockets, sorti en 2001 sur Game Boy Advance. Le jeu est en 2D pixel art. Le jeu est basé sur le dessin animé Inspecteur Gadget.', 'https://fr.wikipedia.org/wiki/Inspector_Gadget:_Advance_Mission'),
  ('Q6126468', 'It''s Mr Pants (initié sous le titre Donkey Kong: Coconut Crackers) est un jeu vidéo développé par Rare et édité par THQ sur Game Boy Advance en 2004.', 'https://fr.wikipedia.org/wiki/It%27s_Mr._Pants'),
  ('Q3718598', 'Ecks vs. Sever est un jeu vidéo de tir à la première personne développé par Crawfish Interactive et édité par Bam! Entertainment, sorti en 2001 sur Game Boy Advance. Il est adapté sur le scénario initial du film Ballistic sorti l''année suivante. Une suite, Ballistic: Ecks vs. Sever, est sortie en 2002 et suit quant à elle le scénario final du film.', 'https://fr.wikipedia.org/wiki/Ecks_vs._Sever'),
  ('Q6917976', 'Moto Racer Advance est un jeu vidéo de course développé par Adeline Software International et édité par Ubisoft, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Moto_Racer_Advance'),
  ('Q6804438', 'Mech Platoon est un jeu vidéo de stratégie en temps réel développé par Will et édité par Kemco, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Mech_Platoon'),
  ('Q374820', 'Darius est un jeu vidéo d''arcade développé en 1986 par Taito.', 'https://fr.wikipedia.org/wiki/Darius_(jeu_vid%C3%A9o)'),
  ('Q6305392', 'Juka and the Monophonic Menace est un jeu vidéo de type action-RPG développé par Orbital Media et édité par Zoo Digital Publishing, sorti en 2005 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Juka_and_the_Monophonic_Menace'),
  ('Q1853367', 'Virtua Tennis (Power Smash au Japon) est un jeu vidéo de tennis développé par Sega AM3 et édité par Sega, initialement sorti sur borne d''arcade en 1999, sur le système Sega NAOMI.

Le jeu est adapté sur Dreamcast en 2000, puis sur Windows, Game Boy Advance et N-Gage. Sa version Dreamcast bénéficie d''un accueil critique favorable, notamment pour son accessibilité et son mode multijoueur.', 'https://fr.wikipedia.org/wiki/Virtua_Tennis_(jeu_vid%C3%A9o)'),
  ('Q2484133', 'Mega Man Zero (Rockman Zero au Japon) est un jeu d''action-plates-formes développé par Inti Creates et édité par Capcom en 2002 sur Game Boy Advance. Il fait partie de la franchise Mega Man et est le premier de la série dérivée Mega Man Zero. Il est réédité dans la compilation Mega Man Zero Collection sur Nintendo DS en 2010 et sur la console virtuelle de la Wii U en 2014.', 'https://fr.wikipedia.org/wiki/Mega_Man_Zero_(jeu_vid%C3%A9o)'),
  ('Q5505248', 'Frogger''s Adventures: Temple of the Frog est un jeu vidéo de plates-formes développé par Konami Software Shanghai et édité par Konami, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Frogger%27s_Adventures:_Temple_of_the_Frog'),
  ('Q5514771', 'GT Advance 3: Pro Concept Racing (Advance GTA 2 au Japon) est un jeu vidéo de course développé par MTO et édité par THQ, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/GT_Advance_3:_Pro_Concept_Racing'),
  ('Q5514768', 'GT Advance 2: Rally Racing (Advance Rally au Japon) est un jeu vidéo de course développé par MTO et édité par THQ, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/GT_Advance_2:_Rally_Racing'),
  ('Q5530293', 'Gekido Advance: Kintaro''s Revenge est un jeu vidéo de type beat them all développé par Naps Team et édité par Zoo Digital Publishing, sorti en 2002 sur Game Boy Advance.

Il fait suite à Gekido: Urban Fighters sur PlayStation.', 'https://fr.wikipedia.org/wiki/Gekido_Advance:_Kintaro%27s_Revenge'),
  ('Q3967342', 'Crash Bandicoot: Fusion et Spyro: Fusion (Crash Bandicoot Purple: Ripto''s Rampage et Spyro Orange: The Cortex Conspiracy aux États-Unis) sont des jeu vidéo de plates-formes, développés par Vicarious Visions et édités par Vivendi Games, sorti sur Game Boy Advance le 3 juin 2004 aux États-Unis.

Ces jeux sont des crossover avec l''univers de Crash Bandicoot et de Spyro the Dragon.', 'https://fr.wikipedia.org/wiki/Crash_Bandicoot_:_Fusion_et_Spyro_:_Fusion'),
  ('Q4017481', 'WWE Survivor Series est un jeu vidéo de catch professionnel développé par Natsume et publié par THQ pour console portable Game Boy Advance. Il se base sur le pay-per-view annuel du même nom, Survivor Series, organisé par la société américaine World Wrestling Entertainment (WWE). Il s''agit de la suite du jeu vidéo Road to WrestleMania X8. WWE Survivor Series est également le dernier jeu WWE à être commercialisé sur console Nintendo jusqu''à l''arrivée de WWE SmackDown vs. Raw 2008 sur Nintendo DS en 2007.

Deux ans après la dernière sortie du précédent opus sur Game Boy Advance, les personnages changent, varient et présentent huit catcheurs de la branche Raw, et huit de la branche SmackDown!. Le mode histoire a été revu puis inclut la Brand Extension de 2002, permettant au joueur de changer de branche.', 'https://fr.wikipedia.org/wiki/WWE_Survivor_Series_(jeu_vid%C3%A9o)'),
  ('Q5591947', 'Gradius Advance, connu au Japon sous le titre Gradius Generation ou bien Gradius Galaxies en Amérique du Nord, est un jeu vidéo de type shoot them up développé par Mobile21 et édité par Konami en 2001 sur Game Boy Advance.

Le jeu se situe chronologiquement entre Gradius III et Gradius Gaiden.', 'https://fr.wikipedia.org/wiki/Gradius_Advance'),
  ('Q5574528', 'Go! Go! Beckham! Adventure on Soccer Island est un jeu vidéo d''action et de plates-formes développé par Denki et édité par Rage Software, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Go!_Go!_Beckham!_Adventure_on_Soccer_Island'),
  ('Q2357489', 'Wario Land 4 (ou Wario Land Advance au Japon) est un jeu vidéo de plateformes sorti en 2001 sur Game Boy Advance. Le jeu a été développé par Nintendo R&D1 et édité par Nintendo.', 'https://fr.wikipedia.org/wiki/Wario_Land_4'),
  ('Q2569478', 'Advance Wars 2: Black Hole Rising est un jeu vidéo de tactique au tour par tour sorti sur Game Boy Advance en 2003. Il est la suite directe du premier Advance Wars, sortie sur cette même console. Un remake nommé Advance Wars 1+2: Re-Boot Camp, incluant également le premier opus, est sorti le 21 avril 2023 sur Nintendo Switch.', 'https://fr.wikipedia.org/wiki/Advance_Wars_2:_Black_Hole_Rising'),
  ('Q2736150', 'Yoshi''s Universal Gravitation (ou Yoshi Topsy-Turvy aux États-Unis) est un jeu vidéo de plate-forme sorti en 2004 sur Game Boy Advance. Le jeu a été développé par Artoon et édité par Nintendo.', 'https://fr.wikipedia.org/wiki/Yoshi%27s_Universal_Gravitation'),
  ('Q2308154', 'Extreme Ghostbusters: Code Ecto-1 est un jeu vidéo d''action-plates-formes, développé par Magic Pockets et édité par LSP Games sur Game Boy Advance en 2002. Il s''inspire de la série télévisée Extrême Ghostbusters, dérivé du film SOS Fantômes sortie en 1984.', 'https://fr.wikipedia.org/wiki/Extreme_Ghostbusters:_Code_Ecto-1'),
  ('Q2569809', 'Spyro Adventure (Spyro: Attack of the Rhynocs) est un jeu vidéo de plates-formes, développé par Digital Eclipse Software, sorti sur Game Boy Advance en 2003. Il s''agit du septième épisode de la série de jeux vidéo Spyro the Dragon et du troisième sur console portable.', 'https://fr.wikipedia.org/wiki/Spyro_Adventure'),
  ('Q2569862', 'Spyro 2: Season of Flame est un jeu vidéo de plates-formes sorti le 18 octobre 2002 exclusivement sur Game Boy Advance. Il fait partie de la série Spyro the Dragon.', 'https://fr.wikipedia.org/wiki/Spyro_2:_Season_of_Flame'),
  ('Q5575297', 'The King of Fighters EX2: Howling Blood est un jeu vidéo de combat développé et édité par Marvelous Entertainment, sorti en 2003 sur Game Boy Advance. Il fait suite à The King of Fighters EX: Neo Blood.

C''est une adaptation de The King of Fighters 2000.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_EX2:_Howling_Blood'),
  ('Q2712856', 'Mega Man Zero 2 (Rockman Zero 2au Japon) est un jeu d''action-plates-formes développé par Inti Creates et édité par Capcom en 2003 sur Game Boy Advance. Il fait partie de la franchise Mega Man et est le second de la série dérivée Mega Man Zero. Il est réédité dans la compilation Mega Man Zero Collection sur Nintendo DS en 2010 et sur la console virtuelle de la Wii U en 2015.', 'https://fr.wikipedia.org/wiki/Mega_Man_Zero_2'),
  ('Q2500267', 'Spyro: Season of Ice est un jeu vidéo de plate-forme développé par Digital Eclipse, sorti sur Game Boy Advance en 2001. Il s''agit du premier épisode de la série Spyro the Dragon sur Game Boy Advance, ainsi que le premier non-développé par Insomniac Games.', 'https://fr.wikipedia.org/wiki/Spyro:_Season_of_Ice'),
  ('Q2565269', 'ChuChu Rocket! est un jeu vidéo de puzzle développé par Sonic Team et édité par Sega, sorti au Japon en 1999 et en Amérique du Nord et en Europe en 2000 sur Dreamcast. Il s''agit du premier sur cette console à exploiter la possibilité de se connecter à Internet pour jouer à plusieurs.

Le jeu a connu plusieurs portages, notamment sur Game Boy Advance.

Il a pour suite ChuChu Rocket! Universe.', 'https://fr.wikipedia.org/wiki/ChuChu_Rocket!'),
  ('Q4274305', 'Blender Bros. est un jeu vidéo d''action-plates-formes développé par Hudson Soft et édité par Infogrames sur Game Boy Advance en 2002. Il a ensuite été réédité sur PC en 2020 par Piko Interactive.', 'https://fr.wikipedia.org/wiki/Blender_Bros.'),
  ('Q389344', 'Wings est un jeu vidéo de type simulateur de vol de combat développé et édité par le studio américain Cinemaware et publié à l''origine en 1990 sur Amiga. Le jeu place le joueur dans l’aviation de la Première Guerre mondiale à travers une campagne scénarisée mêlant dogfights, missions de bombardement et attaques au sol.', 'https://fr.wikipedia.org/wiki/Wings_(jeu_vid%C3%A9o)'),
  ('Q2342264', 'Golden Sun: L''Âge perdu est un jeu vidéo sorti en 2003 sur Game Boy Advance. Il s''agit du second épisode d''un jeu de rôle en deux parties, le premier s''appelant Golden Sun sorti un an plus tôt, également sur Game Boy Advance.

Un troisième opus, Golden Sun: Obscure Aurore, se déroulant 30 ans plus tard est sorti sur Nintendo DS en 2010.', 'https://fr.wikipedia.org/wiki/Golden_Sun_:_L%27%C3%82ge_perdu'),
  ('Q4035489', 'Buffy contre les vampires: La Colère de Darkhul (Buffy the Vampire Slayer: Wrath of the Darkhul King) est un jeu vidéo développé par Natsume, édité par THQ et sorti en 2003 sur Game Boy Advance. Il s''agit d’un beat them all avec 16 niveaux de jeu. C''est le troisième jeu vidéo basé sur la série télévisée Buffy contre les vampires.', 'https://fr.wikipedia.org/wiki/Buffy_contre_les_vampires_:_La_Col%C3%A8re_de_Darkhul'),
  ('Q2012171', 'Metroid: Zero Mission est un jeu d''action-aventure en deux dimensions à défilement latéral développé par Nintendo R&D1 et édité par Nintendo sur Game Boy Advance en 2004. C''est un remake du premier jeu de la série sorti en 1986 simplement intitulé Metroid, qui a pour but de remanier cet opus en intégrant un gameplay similaire à celui de Super Metroid.

Comme dans la plupart des autres jeux de la série, le joueur contrôle la protagoniste nommée Samus Aran, une chasseuse de primes qui explore la planète Zèbes pour éliminer les Pirates de l''espace, qui réalisent des expérimentations sur les métroïdes dans le but de les dupliquer et utiliser leur puissance à leur propres fins. Le gameplay privilégie l''exploration et la recherche de power-ups, qui permettent de débloquer des zones précédemment inaccessibles, ouvrant d''autres espaces à explorer, et ainsi d''avancer dans le jeu. Ce remake propose de nombreux éléments nouveaux comme des objets, des zones inédites, des mini-boss, plusieurs niveaux de difficulté, et un scénario remanié qui permet d''explorer le passé de Samus.', 'https://fr.wikipedia.org/wiki/Metroid:_Zero_Mission'),
  ('Q2015472', 'WWE Road to WrestleMania X8 est un jeu vidéo commercialisé sur console portable Game Boy Advance par THQ, basé sur le pay-per-view du même nom propriété de la fédération de catch professionnel World Wrestling Entertainment (WWE). Le jeu expose des graphismes et une jouabilité mieux développé que ces prédécesseurs. Le jeu est précédé par WWF Road to WrestleMania et suivi par WWE Survivor Series.', 'https://fr.wikipedia.org/wiki/WWE_Road_to_WrestleMania_X8'),
  ('Q2015488', 'WWF Road to WrestleMania est un jeu vidéo commercialisé sur console portable Game Boy Advance par THQ, basé sur l''univers du pay-per-view de la World Wrestling Federation du même nom. Il est le tout premier jeu vidéo de la WWF à être commercialisé sur Game Boy Advance. La partie principale est le mode saison dans lequel les joueurs doivent gagner des matches dans le but d''obtenir le titre des championnats poids-lourds.

Le jeu est suivi par WWE Road to WrestleMania X8.', 'https://fr.wikipedia.org/wiki/WWF_Road_to_WrestleMania'),
  ('Q2291309', 'Castlevania: Aria of Sorrow, intitulé Castlevania: Akatsuki no Menuetto au Japon, est un jeu vidéo de type metroidvania développé et édité par Konami, sorti en 2003 sur Game Boy Advance. Il est le troisième opus de la série Castlevania paru sur ce support. Le jeu est produit par Koji Igarashi.

Aria of Sorrow réutilise les nouveaux éléments de jeu introduits par Castlevania: Symphony of the Night.', 'https://fr.wikipedia.org/wiki/Castlevania:_Aria_of_Sorrow'),
  ('Q4951731', 'Boxing Fever est un jeu vidéo de combat de boxe anglaise développé par Digital Fiction et édité par Majesco Entertainment, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Boxing_Fever'),
  ('Q2478949', 'Metroid: Fusion (ou simplement Fusion, ainsi que Metroid IV et Metroid 4) est un jeu vidéo d''action-aventure en deux dimensions développé par Nintendo R&D1 et édité par Nintendo sur Game Boy Advance le 19 novembre 2002 aux États-Unis, le 22 novembre 2002 en Europe et le 14 février 2003 au Japon.

La chasseuse de primes Samus Aran est infectée par les parasites X lors d''une mission de routine sur la planète SR388. Elle est sauvée de la mort par les médecins de la fédération galactique, qui lui retirent son armure infectée et lui injectent de l''ADN du dernier métroïde afin de la soigner. Dès son rétablissement, la Fédération l''envoie sur la station spatiale de recherche de Biométrix, dans le but d''éradiquer les X qui l''ont totalement colonisée. Guidée par l''ordinateur de bord, la conscience d''Adam Malkovich, Samus élimine la menace X, un dernier métroïde oméga et le SA-X, un clone d''elle-même créé par les X, puis fait exploser la station. Le jeu offre un contenu bonus grâce à une connectivité avec Metroid Prime, à l''aide du câble Nintendo GameCube-Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Metroid:_Fusion'),
  ('Q5533579', 'Gensō Suikoden Card Stories est un opus dérivé de la franchise Suikoden de Konami qui comprend à la fois un jeu Game Boy Advance et un jeu de cartes à collectionner physique. Tous deux ont été publiés à l’automne 2001 au Japon et n’ont pas été traduits officiellement dans d’autres langues. Cependant, une traduction anglaise du jeu vidéo a été réalisée par des fans.

Contrairement à d’autres domaines de la franchise Suikoden, dans lesquels l’ intrigue est un élément essentiel du jeu, Card Stories se concentre principalement sur les combats de cartes et moins sur l’intrigue.

La plupart des cartes représentent des personnages qui font à la fois partie de la série de jeux vidéo de rôle de Suikoden et Suikoden II de Konami. Plusieurs cartes présentent également des personnages qui apparaîtront plus tard dans Suikoden III.', 'https://fr.wikipedia.org/wiki/Gens%C5%8D_Suikoden_Card_Stories'),
  ('Q2019474', 'Tales of the World: Narikiri Dungeon 2 est un spin-off de la série Tales of, développé et édité par Namco. Le jeu est sorti uniquement sur le territoire nippon sur Game Boy Advance le 25 octobre 2002. Tales of the World: Narikiri Dungeon 2 est le premier opus de la série dérivée Tales of the World, connue pour sa capacité à rassembler différents personnages issus des jeux vidéo de la série Tales of. Comme dans son prédécesseur, Tales of Phantasia: Narikiri Dungeon, il s''agit de traverser de nombreux donjons.', 'https://fr.wikipedia.org/wiki/Tales_of_the_World:_Narikiri_Dungeon_2'),
  ('Q2306443', 'Kirby et le Labyrinthe des Miroirs connu sous le nom de Kirby des étoiles: le grand labyrinthe du miroir au Japon ou Kirby and the Amazing Mirror en anglais, est un jeu vidéo de plate-forme sorti en 2004 sur Game Boy Advance. Le jeu a été développé par Flagship puis édité par Nintendo.', 'https://fr.wikipedia.org/wiki/Kirby_et_le_Labyrinthe_des_Miroirs');

insert into import_summary (wikidata_id, summary, source) values
  ('Q1545555', 'Golden Sun est un jeu vidéo sorti en 2001 sur Game Boy Advance. Il s''agit du premier épisode de la série de jeux de rôle Golden Sun.', 'https://fr.wikipedia.org/wiki/Golden_Sun_(jeu_vid%C3%A9o)'),
  ('Q2003093', 'Digimon Battle Spirit 2 est un jeu vidéo d''action et de combat, développé par Dimps et édité par Bandai, appartenant à la franchise japonaise Digimon. Comme pour le précédent opus, Digimon Battle Spirit, le jeu est exclusivement paru sur WonderSwan Color au Japon en 2002 sous le titre de Digimon Frontier: Battle Spirit. Le jeu est ensuite importé puis commercialisé le 24 septembre 2003 aux États-Unis, et le 27 août 2004 en Europe sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Digimon_Battle_Spirit_2'),
  ('Q3962987', 'Smashing Drive est un jeu vidéo de course développé et édité par Gaelco initialement sur borne d''arcade, sorti en 2000. Il a été porté sur GameCube, Xbox et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Smashing_Drive'),
  ('Q3977615', 'Super Robot Taisen R est un jeu vidéo de type tactical RPG développé par AI et édité par Banpresto, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Super_Robot_Taisen_R'),
  ('Q5523136', 'Garfield et ses neuf vies (Garfield and His Nine Lives) est un jeu vidéo d''action développé par Lucky Jump édité par The Game Factory, sorti en 2006 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Garfield_et_ses_neuf_vies'),
  ('Q4274898', 'Boktai 2: Solar Boy Django est un jeu vidéo de type action-RPG développé et édité par l''entreprise japonaise Konami. Il sort sur Game Boy Advance en 2004. Il fait suite à Boktai: The Sun is in Your Hand.', 'https://fr.wikipedia.org/wiki/Boktai_2:_Solar_Boy_Django'),
  ('Q211858', 'DK: King of Swing est un jeu vidéo développé par Paon et édité par Nintendo sur Game Boy Advance en 2005.', 'https://fr.wikipedia.org/wiki/DK_King_of_Swing'),
  ('Q2734887', 'Tactics Ogre: The Knight of Lodis est un jeu vidéo de rôle tactique développé par Quest et édité par Nintendo au Japon, et par Atlus en Amérique du Nord. Ce jeu fait partie de la série Ogre Battle. Le titre est sorti sur Game Boy Advance le 21 juin 2001 au Japon et le 7 mai 2002 en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Tactics_Ogre:_The_Knight_of_Lodis'),
  ('Q5282474', 'Disney Sports: Football (Disney Sports: Soccer) est un jeu vidéo de football développé et édité par Konami, sorti en 2002 sur GameCube et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Disney_Sports:_Football'),
  ('Q2517463', 'Pokémon Pinball: Rubis et Saphir est un jeu vidéo de flipper inspiré par les Pokémon de Nintendo.

Le concept reste le même que celui du premier opus, Pokémon Pinball, sorti sur Game Boy Color.

Le jeu reprend le même gameplay que n''importe quel autre jeu de flipper et y insère des éléments tirés de l''univers Pokémon. D''abord, les monstres eux-mêmes sont capturables au cours de la partie; ensuite, il est possible de faire évoluer les Pokémon grâce à une sorte de mini-jeu.', 'https://fr.wikipedia.org/wiki/Pok%C3%A9mon_Pinball_:_Rubis_et_Saphir'),
  ('Q1574163', 'Mario vs. Donkey Kong est un jeu vidéo de plate-forme et réflexion sorti en 2004 sur Game Boy Advance. Directement inspiré de Donkey Kong sorti en 1994 sur Game Boy, le jeu a été développé par Nintendo Software Technology et édité par Nintendo. Deux suite sont sorties sur Nintendo DS et portent le nom de Mario vs. Donkey Kong 2: March of the Minis et Mario vs. Donkey Kong: Pagaille à Mini-Land !.

Une réédition sur Nintendo Switch a été annoncée lors du Nintendo Direct du 14 septembre 2023 pour une sortie le 16 février 2024.', 'https://fr.wikipedia.org/wiki/Mario_vs._Donkey_Kong_(jeu_vid%C3%A9o)'),
  ('Q2513822', 'Rayman: La Revanche des Hoodlums (Rayman Hoodlums'' Revenge) est un jeu vidéo de la série Rayman sorti sur Game Boy Advance en 2005. Il met en scène la revanche d''André, le chef des Hoodlums dans Rayman 3: Hoodlum Havoc. Il reprend le principe des « lessives laser » qui donnent des pouvoirs spéciaux à Rayman.

Le jeu est réalisé en 3D isométrique contrairement aux précédents sur la console portable Nintendo.

Contrairement à la plupart des épisodes de Rayman, celui-ci n''a été édité que pour la Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Rayman_:_La_Revanche_des_Hoodlums'),
  ('Q731919', 'Dragon Ball Z: Supersonic Warriors est un jeu vidéo de combat développé par Arc System Works. Le jeu est disponible depuis 2004 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_Supersonic_Warriors'),
  ('Q740515', 'Madagascar est un jeu vidéo d''action-aventure et de plate-forme, développé en 2005 par Toys For Bob pour la PlayStation 2, la Xbox, PC, la Nintendo DS, la Game Boy Advance et la GameCube. Le jeu est basé sur le film d''animation éponyme. Il précède différents jeux vidéo basés sur la licence de DreamWorks, dont Madagascar: Operation Penguin sorti en 2005 sur Game Boy Advance, Madagascar 2 en 2008 et Madagascar 3 en 2012.', 'https://fr.wikipedia.org/wiki/Madagascar_(jeu_vid%C3%A9o)'),
  ('Q2001228', 'Dynasty Warriors Advance est un jeu vidéo de type hack ''n'' slash développé par Omega Force et édité par Koei, sorti en 2005 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Dynasty_Warriors_Advance'),
  ('Q3957907', 'Serious Sam Advance (ou simplement Serious Sam en Amérique du Nord) est un jeu vidéo de tir à la première personne développé par Climax Solent et édité par Global Star Software, sorti en 2004 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Serious_Sam_Advance'),
  ('Q7121849', 'Pac-Man Pinball Advance est un jeu vidéo de flipper développé par HumanSoft et édité par Namco, sorti en 2005 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Pac-Man_Pinball_Advance'),
  ('Q5985324', 'Ice Nine est un jeu vidéo de tir à la première personne développé par Torus Games et édité par Bam! Entertainment, sorti en 2005 sur Game Boy Advance.

Initialement, le jeu devait être une adaptation du film La Recrue. Une version PlayStation 2 était prévue mais a été annulée.', 'https://fr.wikipedia.org/wiki/Ice_Nine'),
  ('Q6470527', 'Lady Sia est un jeu vidéo de plates-formes développé par RFX Interactive et édité par TDK Mediactive, sorti en 2001 sur Game Boy Advance. Sorti aux États-Unis le 15 octobre 2001 et sorti en Europe le 19 octobre 2001. Lady Sia est l''un des rares jeux originaux produits par RFX Interactive.', 'https://fr.wikipedia.org/wiki/Lady_Sia'),
  ('Q6518566', 'Lego Knights'' Kingdom est un jeu vidéo d''action-aventure développé par Razorback Developments et édité par THQ, sorti en 2004 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Lego_Knights%27_Kingdom'),
  ('Q5956754', 'Héros de la Ligue des justiciers: Flash (Justice League Heroes: The Flash) est un jeu vidéo d''action développé par WayForward Technologies et édité par Warner Bros. Interactive Entertainment, sorti en 2006 sur Game Boy Advance.

Il s''agit d''un jeu dérivé de Héros de la Ligue des justiciers.', 'https://fr.wikipedia.org/wiki/H%C3%A9ros_de_la_Ligue_des_justiciers_:_Flash'),
  ('Q5910242', 'Hot Potato! est un jeu vidéo d''action et de puzzle développé par Pukka Games et édité par BAM! Entertainment, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Hot_Potato!'),
  ('Q7093915', 'Onimusha Tactics est un jeu vidéo de type tactical RPG développé et édité par Capcom, sorti en 2003 sur Game Boy Advance. Il a été réédité en 2015 sur la Console virtuelle de la Wii U.', 'https://fr.wikipedia.org/wiki/Onimusha_Tactics'),
  ('Q7642148', 'Glory Days: The Essence of War (Super Army War en Amérique du Nord) est un jeu vidéo de type shoot ''em up développé par ODenis Studio et édité par Neko Entertainment, sorti en 2005 sur Game Boy Advance.

Il a pour suite Glory Days 2 sur Nintendo DS et Glory Days: Tactical Defense sur DSiWare.', 'https://fr.wikipedia.org/wiki/Glory_Days:_The_Essence_of_War'),
  ('Q7547922', 'Snood est un jeu vidéo de puzzle programmé par Dave Dobson. Snood est sorti pour Mac OS en 1996 en tant que shareware, puis pour MS-DOS et Microsoft Windows en 1999. Une adaptation pour Game Boy Advance a été développée par Rebellion Developments et publiée par Destination Software en 2001, tandis qu''une version iOS a été développée par Iron Galaxy et publiée par EA Mobile le 8 mai 2009. Dobson a fondé Snood, LLC pour vendre le jeu.

Comme dans Puzzle Bobble, la connexion de trois Snoods identiques ou plus les fait disparaître du tableau. Lorsque le tableau est vidé par le joueur, le jeu passe au niveau suivant. Si les Snoods atteignent le bas de l''écran, une vie est perdue. La partie n''est pas limitée dans le temps dans la plupart des modes de jeu.', 'https://fr.wikipedia.org/wiki/Snood'),
  ('Q7487408', 'Shaman King: Master of Spirits est un jeu vidéo de type metroidvania développé et édité par Konami sorti en 2004 sur Game Boy Advance, basé sur l''univers du manga Shaman King.', 'https://fr.wikipedia.org/wiki/Shaman_King:_Master_of_Spirits'),
  ('Q7355500', 'Rockman.EXE 4.5 Real Operation est un tactical RPG développé par Capcom Production Studio 2 et édité par Capcom sur Game Boy Advance au Japon en 2004. Il fait partie de la série dérivée Mega Man Battle Network et ne fait pas partie de l''histoire de cette série.', 'https://fr.wikipedia.org/wiki/Rockman.EXE_4.5:_Real_Operation'),
  ('Q632632', 'Scurge: Hive est un jeu d''action développé par Orbital Media, sorti le 26 octobre 2006 sur Nintendo DS et Game Boy Advance. Il a reçu des notes correctes sur la plupart des sites et magazines consacrés aux jeux vidéo.', 'https://fr.wikipedia.org/wiki/Scurge:_Hive'),
  ('Q625317', 'Jurassic Park III: The DNA Factor est un jeu vidéo d''action développé par Konami Computer Entertainment Hawaii et édité par Konami, sorti en 2001 sur Game Boy Advance. Il est adapté du film Jurassic Park III.', 'https://fr.wikipedia.org/wiki/Jurassic_Park_3:_The_DNA_Factor'),
  ('Q7038903', 'Ninja Cop (Ninja Five-O au Japon et en Amérique du Nord) est un jeu vidéo d''action développé par Hudson Soft et édité par Konami, sorti en 2003 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Ninja_Cop'),
  ('Q7044930', 'No Rules: Get Phat est un jeu vidéo d''action et de plates-formes développé par Flying Tiger Development et édité par TDK Mediactive Inc., sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/No_Rules:_Get_Phat'),
  ('Q622386', 'Konami Krazy Racers (Konami Wai Wai Racing Advance en version originale japonaise) est un jeu vidéo de course développé et édité par Konami, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Konami_Krazy_Racers'),
  ('Q7396363', 'Sabre Wulf est un jeu vidéo de plates-formes développé par Rare et édité par THQ, sorti en 2004 sur Game Boy Advance et téléphone mobile.

Il reprend le personnage de Sabreman de Sabre Wulf, sorti en 1984.', 'https://fr.wikipedia.org/wiki/Sabre_Wulf_(jeu_vid%C3%A9o,_2004)'),
  ('Q6432477', 'Koro Koro Puzzle Happy Panechu! est un jeu vidéo de type puzzle game développé par Mobile21 et Nintendo R&D2, et édité par Nintendo pour la Game Boy Advance. Il sort exclusivement au Japon le 8 mars 2002. C''est le premier jeu de cette console de jeux vidéo à utiliser le gyroscope.', 'https://fr.wikipedia.org/wiki/Koro_Koro_Puzzle_Happy_Panechu!'),
  ('Q7156698', 'Payback est un jeu vidéo développé et publié par Apex Designs. Il a été publié pour la première fois en 2001. Il a été suivi d''une suite en 2012, Payback 2.', 'https://fr.wikipedia.org/wiki/Payback_(jeu_vid%C3%A9o)'),
  ('Q7100014', 'Orbient (Orbital au Japon) est un jeu vidéo de puzzle développé par Skip et édité par Nintendo, sorti en 2006 sur Game Boy Advance (dans la série bit Generations) et en 2009 sur WiiWare (dans la série Art Style).', 'https://fr.wikipedia.org/wiki/Orbient'),
  ('Q7413099', 'Samurai Jack: The Amulet of Time est un jeu vidéo de type metroidvania développé par Virtucraft Studios et édité par Bam! Entertainment, sorti en 2003 sur Game Boy Advance.

Il est basé sur la série d''animation Samouraï Jack.', 'https://fr.wikipedia.org/wiki/Samurai_Jack:_The_Amulet_of_Time'),
  ('Q7888526', 'Zone of the Enders: The Fist of Mars (Z.O.E. 2173: Testament au Japon), est un jeu vidéo de type tactical RPG développé par Winkysoft et édité par Konami en 2001 sur Game Boy Advance.

Le jeu fait partie de l''univers fictionnel Zone of the Enders.', 'https://fr.wikipedia.org/wiki/Zone_of_the_Enders:_The_Fist_of_Mars'),
  ('Q843205', 'Kingdom Hearts: Chain of Memories est un jeu vidéo de type action-RPG développé par Jupiter et édité par Square Enix sur Game Boy Advance disponible depuis novembre 2004 au Japon et depuis mai 2005 en Europe. Chain of Memories est un épisode de la série Kingdom Hearts qui se situe dans la continuité du premier volet et permet de mieux comprendre les évènements de Kingdom Hearts 2. Il se situe donc entre Kingdom Hearts et Kingdom Hearts 2.', 'https://fr.wikipedia.org/wiki/Kingdom_Hearts:_Chain_of_Memories'),
  ('Q775291', 'Spy Hunter (stylisé SpyHunter) est un jeu vidéo de combat motorisé édité par Midway Games, sorti en 2002 sur PlayStation 2, Xbox, GameCube, Windows, Mac OS et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Spy_Hunter_(jeu_vid%C3%A9o,_2001)'),
  ('Q7229281', 'Popeye: Rush for Spinach est un jeu vidéo de plates-formes et de course à pied sorti sur Game Boy Advance en 2006 développé par Magic Pockets et édité par Namco et Atari. Il exploite la licence Popeye.', 'https://fr.wikipedia.org/wiki/Popeye:_Rush_for_Spinach'),
  ('Q765425', 'Sonic Advance 3 est un jeu de plates-formes développé par Dimps sous la supervision de Sonic Team, et édité par Sega sur Game Boy Advance. Il est sorti le 7 juin 2004 en Amérique du Nord, puis le 17 juin au Japon et le 18 juin en Europe. Il fait partie de la franchise Sonic et fait suite à Sonic Advance 2 (2002) ainsi qu''à Sonic Battle (2003).', 'https://fr.wikipedia.org/wiki/Sonic_Advance_3'),
  ('Q7742425', 'The Invincible Iron Man est un jeu vidéo d''action développé par Torus Games et édité par Activision, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/The_Invincible_Iron_Man_(jeu_vid%C3%A9o)'),
  ('Q755186', 'Doom II: Hell on Earth est un jeu vidéo de tir à la première personne (FPS) développé par id Software et publié sur MS-DOS par GT Interactive le 30 septembre 1994 en Amérique du Nord et le 10 octobre 1994 en Europe.

Le jeu a également été porté sur Macintosh en 1995, sur Game Boy Advance en 2002, puis sur Xbox et Xbox 360 en 2010 et en 2012 respectivement.

Doom II fait suite à Doom, publié en 1993 et s’inscrit dans la lignée du précédent titre développé par id Software, Wolfenstein 3D. Le jeu se déroule dans un futur proche peu après les événements décrits dans Doom, le joueur incarnant un Marine spatial (le Doomguy) découvrant que la Terre a été envahie par des démons à son retour de l’enfer. Pour sauver l’humanité, le joueur doit d’abord aider les survivants à s’enfuir à bord d’un vaisseau spatial avant de s’attaquer à la source de l’invasion. Pour cela, il doit traverser des niveaux peuplés de nombreuses créatures hostiles qu’il peut combattre à l''aide des armes et des bonus trouvés au fur et à mesure de son avancée dans le jeu.', 'https://fr.wikipedia.org/wiki/Doom_II:_Hell_on_Earth'),
  ('Q2068675', 'Mario Kart: Super Circuit, connu sous le nom de Mario Kart Advance au Japon, est l''épisode Game Boy Advance de la franchise Mario Kart sorti en 2001, qui met en scène des courses de karting dans l''univers de Super Mario.

Le jeu utilise le mode 7 (déjà vu dans Super Mario Kart sur Super Nintendo) qui est en fait de la semi-3D. Le jeu s''est vendu à 5,94 millions d''unités dans le monde. Le jeu présente aussi deux autres similitudes majeures avec Super Mario Kart: le retour des pièces et de la totalité des circuits du premier opus.

Le jeu est réédité sur la console virtuelle de la Nintendo 3DS en 2011, puis sur la console virtuelle de la Wii U en 2015 et sur le Nintendo Switch Online en 2023.', 'https://fr.wikipedia.org/wiki/Mario_Kart:_Super_Circuit'),
  ('Q7757155', 'The Pinball of the Dead est un jeu vidéo de flipper développé par Wow Entertainment et sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/The_Pinball_of_the_Dead'),
  ('Q761957', 'Crash Bandicoot XS, intitulé Crash Bandicoot: The Huge Adventure aux États-Unis et Crash Bandicoot Advance au Japon, est un jeu vidéo de plates-formes, développé par Vicarious Visions et édité par Universal Interactive Studios, sorti sur Game Boy Advance le 27 février 2002 aux États-Unis, 15 mars 2002 en Europe et le 18 juillet 2002 au Japon. Il fait partie de la série Crash Bandicoot.', 'https://fr.wikipedia.org/wiki/Crash_Bandicoot_XS'),
  ('Q645003', 'Phoenix Wright: Ace Attorney - Justice for All est un jeu vidéo d''aventure développé par Capcom Production Studio 4 et édité par l''entreprise japonaise Capcom. Il sort sur Game Boy Advance en 2002 au Japon. Le jeu est porté sur Nintendo DS en 2006 au Japon et en 2007 en Occident dans une version qui connait un certain succès. Il est également réédité au Japon sur Windows en 2006 puis Wiiware en 2010

Le jeu se déroule un an après le premier épisode et le joueur y incarne toujours Phoenix Wright, un avocat débutant, au cours de quatre affaires, dans lesquelles il devra prouver l''innocence de ses clients à force de preuves et de contre-interrogatoires.', 'https://fr.wikipedia.org/wiki/Phoenix_Wright:_Ace_Attorney_-_Justice_for_All'),
  ('Q7900078', 'Urban Yeti! est un jeu vidéo d''action développé par Cave Barn Studios et édité par Telegames, sorti en 2002 sur Game Boy Advance. Le jeu met en scène un yéti cherchant une femelle dans une ville d''humains. En vue de dessus, le joueur doit accomplir différentes missions. Le jeu a reçu un accueil moyen de la presse à cause de problèmes techniques mais a été apprécié pour son humour.', 'https://fr.wikipedia.org/wiki/Urban_Yeti!'),
  ('Q7959063', 'Wade Hixton''s Counter Punch est un jeu vidéo de combat (boxe anglaise) développé par Inferno Games et édité par Destination Software, sorti en 2004 sur Game Boy Advance et Digiblast.', 'https://fr.wikipedia.org/wiki/Wade_Hixton%27s_Counter_Punch'),
  ('Q721710', 'Phoenix Wright: Ace Attorney - Trials and Tribulations est un jeu vidéo d''aventure et troisième volet de la série Ace Attorney, développé par Capcom Production Studio 4 et édité par l''entreprise japonaise Capcom. Il sort sur Game Boy Advance en 2004 au Japon. Le jeu est porté sur Nintendo DS en 2007 au Japon et aux États-Unis et en 2008 en Europe. Il est également réédité uniquement au Japon sur Windows en 2006 puis Wiiware en 2010.

Le joueur y incarne deux avocats, Phoenix Wright et Mia Fey (à travers des flashbacks), au cours de cinq affaires, dans lesquelles ils devront prouver l''innocence de leurs clients à force de preuves et de contre-interrogatoires.', 'https://fr.wikipedia.org/wiki/Phoenix_Wright:_Ace_Attorney_-_Trials_and_Tribulations'),
  ('Q7279681', 'Racing Gears Advance est un jeu vidéo de course développé par Orbital Media, sorti en 2004 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Racing_Gears_Advance'),
  ('Q663809', 'Jurassic Park III: Park Builder est un jeu vidéo de gestion s''inspirant de l''univers des films Jurassic Park. Développé et édité par Konami, le jeu est sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Jurassic_Park_3:_Park_Builder'),
  ('Q7353400', 'Robotech: The Macross Saga est un jeu vidéo de type shoot ''em up développé par Lucky Chicken Games et édité par TDK Mediactive, sorti en 2002 sur Game Boy Advance.

Il est basé sur l''anime The Super Dimension Fortress Macross (Robotech: The Macross Saga dans les pays anglophones).', 'https://fr.wikipedia.org/wiki/Robotech:_The_Macross_Saga_(jeu_vid%C3%A9o)'),
  ('Q648099', 'Grand Theft Auto Advance (souvent référencé sous le titre Grand Theft Auto ou encore GTA: Advance) est un jeu vidéo d''action-aventure, développé par Digital Eclipse et édité par Take-Two Interactive, commercialisé le 2 janvier 2004 sur console portable Game Boy Advance. Le jeu est intitulé Grand Theft Auto Advance sur son écran titre; la couverture du jeu et tout le contenu promotionnel l''intitule simplement Grand Theft Auto.

Le jeu est joué en vue du dessus. Contrairement aux autres volets Grand Theft Auto, les véhicules du jeu peuvent se retourner. Il s''agit du septième opus de la série Grand Theft Auto, et du troisième Grand Theft Auto développé sur console portable (GTA 1 et 2 sur Game Boy Color).', 'https://fr.wikipedia.org/wiki/Grand_Theft_Auto_Advance'),
  ('Q953229', 'Advance Wars est un jeu vidéo de tactique au tour par tour appartenant à la série de jeux vidéo Nintendo Wars, développé par Intelligent Systems pour Nintendo, sorti sur Game Boy Advance. Le jeu est réalisé par Takehiro Izushi, le cocréateur de la série, et dirigé par Tohru Narihiro.

Le jeu est sorti le 10 septembre 2001 aux États-Unis, et devait sortir plus tard en Europe et au Japon, mais cette date a été mise en attente à la suite des attentats du 11 septembre. La sortie japonaise est alors reportée pour ne finalement jamais voir le jour. C''est une situation inédite, car jusqu''alors, tous les jeux de la série ne sont sortis exclusivement qu''au Japon. Bien qu''ayant également été retardé, il sort en Europe le 11 janvier 2002. Cette version inclut les langues anglaise, allemande, française et espagnole; le choix étant laissé au joueur au démarrage du jeu.', 'https://fr.wikipedia.org/wiki/Advance_Wars'),
  ('Q868057', 'Klonoa: Empire of Dreams est un jeu vidéo de plates-formes développé par Now Production et édité par Namco, sorti à partir de 2001 sur Game Boy Advance. Pour avoir commis le crime de rêver dans l''empire de Jillius, Klonoa le chat aux oreilles particulièrement développées, est contraint de parcourir le monde pour défaire de terribles monstres attaquant depuis peu les civils. Il s''agit du quatrième jeu de la série Klonoa. Il reprend les ingrédients classiques de la série, en mêlant plates-formes et réflexion, en entrecoupant le jeu de phases d''action, le tout dans un monde imaginaire et magique composé de créatures anthropomorphiques.', 'https://fr.wikipedia.org/wiki/Klonoa:_Empire_of_Dreams'),
  ('Q751268', 'Astro Boy: Omega Factor (Astroboy Tetsuwan Atom: Atom Heart no Himitsu en japonais) est un jeu vidéo développé conjointement par le studio Hitmaker de Sega et la compagnie Treasure.

Sorti au Japon sur Game Boy Advance en 2003, ce jeu met en scène les aventures d''Astro, le héros de Osamu Tezuka. Il sera distribué en Europe quatorze mois plus tard dans une version légèrement améliorée.', 'https://fr.wikipedia.org/wiki/Astro_Boy:_Omega_Factor'),
  ('Q806590', 'Banjo-Kazooie: La Revanche de Grunty (Banjo-Kazooie: Grunty''s Revenge) est un jeu vidéo de plates-formes sorti en 2003 sur Game Boy Advance. Le jeu a été développé par Rare puis édité par THQ. C''est le troisième jeu de la série Banjo-Kazooie et le second opus dans l''ordre chronologique. Il se situe donc entre Banjo-Kazooie et Banjo-Tooie. C''est le premier jeu développé par Rare sur une console Nintendo après son rachat par Microsoft.

Le jeu est accompagné par une compilation des mini-jeux sur téléphone mobile sous le titre Banjo Kazooie: Grunty''s Revenge Missions.', 'https://fr.wikipedia.org/wiki/Banjo-Kazooie_:_La_Revanche_de_Grunty'),
  ('Q863600', 'Metal Slug Advance est un jeu vidéo de type Run and gun développé par Noise Factory et édité par SNK Playmore sorti en 2004 sur Game Boy Advance. Il s''agit du deuxième jeu de la série Metal Slug dans lequel le joueur ne peut pas incarner Marco Rossi (le premier étant Metal Slug: 2nd Mission), bien que ce dernier soit visible à l''arrière plan de la jaquette occidentale.', 'https://fr.wikipedia.org/wiki/Metal_Slug_Advance'),
  ('Q953869', 'F-Zero: Maximum Velocity (F-Zero for Game Boy Advance en version originale japonaise) est un jeu vidéo de course développé par Nintendo Cube et édité par Nintendo, sorti en 2001 sur Game Boy Advance. Il s''agit du troisième opus de la série F-Zero. Il était disponible au lancement de la console.', 'https://fr.wikipedia.org/wiki/F-Zero:_Maximum_Velocity'),
  ('Q11350430', 'Mega Man Battle Chip Challenge est un jeu vidéo de type cartes à collectionner développé par Inti Creates et Capcom Production Studio 2 et édité par Capcom en 2003 sur Game Boy Advance et WonderSwan Color. Il est réédité en 2014 sur la console virtuelle de la Wii U.', 'https://fr.wikipedia.org/wiki/Mega_Man_Battle_Chip_Challenge'),
  ('Q11344719', 'Monster Rancher Advance, aussi connu sous le nom de Monster Farm Advance au Japon, est un jeu vidéo Game Boy Advance issu de la série de jeux vidéo Monster Rancher.', 'https://fr.wikipedia.org/wiki/Monster_Rancher_Advance'),
  ('Q8564088', 'Souris City est un jeu vidéo d''action-aventure développé par Monkey Bar Games et édité par D3 Publisher en novembre 2006 sur GameCube et PlayStation 2. Parallèlement, Art Co. a développé une autre version sur Nintendo DS et Altron sur Game Boy Advance.

Il s''agit d''un produit dérivé du film Souris City en jeu vidéo. La plupart des versions ont reçu des critiques négatives.', 'https://fr.wikipedia.org/wiki/Souris_City_(jeu_vid%C3%A9o)'),
  ('Q14906024', 'Game & Watch Gallery Advance (Game & Watch Gallery 4) est le quatrième volet de la série Game & Watch Gallery. Ce jeu est réédité sur la console virtuelle de la Wii U.', 'https://fr.wikipedia.org/wiki/Game_%26_Watch_Gallery_Advance'),
  ('Q16259532', 'Fire Pro Wrestling est un jeu vidéo de combat développé par Human Entertainment et Spike, sorti à partir de 2001 sur Game Boy Advance. Il fait partie de la série Fire Pro Wrestling. Il s''agit du premier de celle-ci sur Game Boy Advance et était disponible au lancement de la console au Japon et aux États-Unis. Il a pour suite Fire Pro Wrestling 2.', 'https://fr.wikipedia.org/wiki/Fire_Pro_Wrestling'),
  ('Q16259109', 'Rampage: Puzzle Attack est un jeu vidéo de puzzle développé par Ninai Games et édité par Midway Games, sorti en 2001 sur Game Boy Advance.

Il met en scène les personnages de Rampage dans duels de puzzle un peu à la manière de Super Puzzle Fighter II Turbo et des autres jeux du genre.', 'https://fr.wikipedia.org/wiki/Rampage:_Puzzle_Attack'),
  ('Q10735303', 'Army Men: Turf Wars est un jeu vidéo d''action développé par Mobius Entertainment et édité par The 3DO Company, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Army_Men:_Turf_Wars'),
  ('Q10322876', 'Madagascar: Opération Pingouins (Madagascar: Operation Penguin) est un jeu vidéo de plates-formes développé par Vicarious Visions et édité par Activision, sorti en 2005 sur Game Boy Advance.

Il met en vedette les pingouins du film Madagascar.', 'https://fr.wikipedia.org/wiki/Madagascar_:_Op%C3%A9ration_Pingouins'),
  ('Q11897282', 'Les Super Nanas ou The Powerpuff Girls est une série d''animation américaine créée par Craig McCracken, produite par Cartoon Network Studios et diffusée aux États-Unis sur Cartoon Network du 18 novembre 1998 au 25 mars 2005.

La série se centre sur les aventures de Belle, Bulle et Rebelle, trois super-héroïnes à l''apparence de petites filles, et de leur créateur, un scientifique du nom de professeur Utonium, résidents dans la ville fictive de Townsville. Les filles sont généralement appelées par le maire de la ville pour combattre divers monstres et antagonistes.

McCracken, animateur et créateur de la série, développe le concept et l''origine des Supers Nanas en 1993 dans un court-métrage d''animation intitulé Whoopass Stew! The Whoopass Girls in: A Sticky Situation durant sa seconde année d''étude au CalArts. Après avoir effectué un changement mineur dans le titre, la chaîne Cartoon Network diffuse le tout premier épisode des Supers Nanas dans un programme nommé World Premiere Toons en 1995 et en 1996 sous le label de Cartoon Cartoon. Un total de 6 saisons et de 78 épisodes ont été diffusés, dont deux courts-métrages: un épisode spécial Noël et un épisode spécial fêtant les dix ans de la série. Cartoon Network produit une nouvelle version de la série diffusée à partir d''avril 2016, aux États-Unis, comme en France.', 'https://fr.wikipedia.org/wiki/Les_Super_Nanas_(s%C3%A9rie_t%C3%A9l%C3%A9vis%C3%A9e_d%27animation,_1998)'),
  ('Q11856168', 'American Dragon: Jake Long - Rise of the Huntsclan est un jeu vidéo de type beat them all développé par WayForward Technologies et édité par Buena Vista Games, sorti en 2006 sur Game Boy Advance.

Il est adapté de la série animée American Dragon: Jake Long.', 'https://fr.wikipedia.org/wiki/American_Dragon:_Jake_Long_-_Rise_of_the_Huntsclan'),
  ('Q16680274', 'Titeuf: Ze Gag Machine est un jeu vidéo d''action, édité par Infogrames et développé par 3D Light Team, commercialisé le 29 novembre 2002 en Amérique du Nord et le 6 décembre 2002 en Europe, sur la console portable Game Boy Advance. Comme pour le premier jeu vidéo commercialisé en 2001 sur Game Boy Color, Titeuf: Ze Gag Machine s''inspire de la série animé (d’après la bande dessinée éponyme créée par l''auteur suisse Zep). Fin 2002, Infogrames dévoile sa liste de jeux prévus dans laquelle Ze Gag Machine figure.', 'https://fr.wikipedia.org/wiki/Titeuf_:_Ze_Gag_Machine'),
  ('Q16640100', 'Gremlins: Stripe vs. Gizmo est un jeu vidéo de plates-formes s''inspirant du film Gremlins sorti en 1984. Le jeu est développé par Magic Pockets et co-édité par LSP Games et Wanadoo Edition (en Europe), et Dreamcatcher Games (en Amérique du Nord) sur Game Boy Advance en 2002.', 'https://fr.wikipedia.org/wiki/Gremlins:_Stripe_vs._Gizmo'),
  ('Q16266774', 'The Revenge of Shinobi est un jeu vidéo d''action et de plates-formes développé par 3d6 Games et édité par Sega, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/The_Revenge_of_Shinobi_(jeu_vid%C3%A9o,_2002)'),
  ('Q16654749', 'Les Quatre Fantastiques: Flame On (Fantastic Four: Flame On) est un jeu vidéo d''action édité par Activision et développé par Torus Games. Le jeu est adapté du film du même nom réalisé par Tim Story sorti en 2005 et se centre sur le personnage de La Torche humaine.', 'https://fr.wikipedia.org/wiki/Les_Quatre_Fantastiques_:_Flame_On'),
  ('Q26157664', 'Daredevil est un jeu vidéo d''action développé par Griptonite Games, sorti en 2003 sur Game Boy Advance. Il est basé sur le film du même nom d''après le comics édité par Marvel. Une version Xbox et PlayStation 2 était développée par 5000ft Inc. mais a été annulée.', 'https://fr.wikipedia.org/wiki/Daredevil_(jeu_vid%C3%A9o)'),
  ('Q25396774', 'The Wild est un jeu vidéo de plates-formes développé par Climax Studios et édité par Buena Vista Games, sorti en 2006 sur Game Boy Advance. Il est adapté du long métrage d''animation de Walt Disney Pictures The Wild.', 'https://fr.wikipedia.org/wiki/The_Wild_(jeu_vid%C3%A9o)'),
  ('Q21039913', 'The Scorpion King: Sword of Osiris est un jeu vidéo de plates-formes développé par WayForward Technologies et édité par Universal Interactive, sorti en 2002 sur Game Boy Advance.

Il fait suite au film Le Roi Scorpion.', 'https://fr.wikipedia.org/wiki/The_Scorpion_King:_Sword_of_Osiris'),
  ('Q25396610', 'xXx, selon la graphie de la jaquette, est un jeu vidéo d''action développé par Digital Eclipse et édité par Activision, sorti en 2002 sur Game Boy Advance. Il est adapté du film xXx.', 'https://fr.wikipedia.org/wiki/XXX_(jeu_vid%C3%A9o)'),
  ('Q24935617', 'Les Aventures de Jackie Chan: La Légende de la main noire (Jackie Chan Adventures: Legend of the Dark Hand) est un jeu vidéo de type beat them all développé par Torus Games et édité par Activision, sorti en 2001 sur Game Boy Advance. Il est adapté de la série télévisée d''animation Jackie Chan.', 'https://fr.wikipedia.org/wiki/Les_Aventures_de_Jackie_Chan_:_La_L%C3%A9gende_de_la_main_noire'),
  ('Q20726215', 'MotoGP: Ultimate Racing Technology est un jeu vidéo de course, développé par Climax et édité par THQ, sorti en Europe en 2002 sur Xbox et Windows. C''est le premier jeu de la série MotoGP: Ultimate Racing Technology. Une adaptation du jeu sur Game Boy Advance et N-Gage sous le titre MotoGP.', 'https://fr.wikipedia.org/wiki/MotoGP:_Ultimate_Racing_Technology'),
  ('Q17514208', 'Frère des ours (Brother Bear) est un jeu vidéo d''action développé par KnowWonder et Vicarious Visions, édité par Disney Interactive. Il est sorti en 2003 sur Windows et Game Boy Advance.

Il est basé sur le film du même nom.', 'https://fr.wikipedia.org/wiki/Fr%C3%A8re_des_ours_(jeu_vid%C3%A9o)'),
  ('Q27964097', 'Spirit, l''étalon des plaines (Spirit: Stallion of the Cimarron) est un jeu vidéo d''action-aventure développé par Hyperspace Cowgirls et édité par THQ, sorti en 2002 sur Game Boy Advance. Il est adapté du long métrage d''animation Spirit, l''étalon des plaines.', 'https://fr.wikipedia.org/wiki/Spirit,_l%27%C3%A9talon_des_plaines_(jeu_vid%C3%A9o)'),
  ('Q29962131', 'Shrek 2: La Charge zéroïque (Shrek 2: Beg for Mercy) est un jeu vidéo d''action et de plates-formes développé par Vicarious Visions et édité par Activision, sorti en 2004 sur Game Boy Advance.

Il est adapté de l''univers du film Shrek 2 et permet au joueur d''incarner le Chat potté.', 'https://fr.wikipedia.org/wiki/Shrek_2_:_La_Charge_z%C3%A9ro%C3%AFque'),
  ('Q29907190', 'Maniac Racers Advance (Motocross Maniacs Advance au Japon et en Amérique du Nord) est un jeu vidéo de course développé et édité par Konami, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Maniac_Racers_Advance'),
  ('Q28494312', 'Astérix et Obélix: Paf ! Par Toutatis ! est un jeu vidéo développé par Bit Managers et édité par Infogrames, sorti en 2002 sur Game Boy Advance.

Il intègre une version améliorée du jeu de plates-formes Astérix et Obélix et un beat them all inédit inspiré d''Astérix et Cléopâtre.', 'https://fr.wikipedia.org/wiki/Ast%C3%A9rix_et_Ob%C3%A9lix_:_Paf_!_Par_Toutatis_!'),
  ('Q29907119', 'Lode Runner est un jeu vidéo de plates-formes et de réflexion développé et édité par Success, sorti en 2003 sur Game Boy Advance. Il fait partie de la gamme SuperLite 1500 Series.', 'https://fr.wikipedia.org/wiki/Lode_Runner_(jeu_vid%C3%A9o,_2003)'),
  ('Q29838430', 'Zidane Football Generation 2002 (Football Generation hors de France, Calcio 2003 en Italie, Zidane Football Generation sur Game Boy Color) est un jeu vidéo de sport développé par Trecision et édité par Comgame 576, sorti en 2001 sur Windows, PlayStation 2, Game Boy Color et Game Boy Advance. Il est ressorti en 2012 sur PlayStation 3 via le PlayStation Network.

La version française porte le nom de Zinédine Zidane.', 'https://fr.wikipedia.org/wiki/Zidane_Football_Generation_2002'),
  ('Q29919720', 'Fila Decathlon est un jeu vidéo de sport développé par Athletic Design AB et édité par THQ, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Fila_Decathlon'),
  ('Q29907070', 'Léa Passion: Vétérinaire (My Pet Hotel sur DS ou My Pet Resort sur GBA) est un jeu vidéo de simulation développé par Independent Arts et édité par Ubisoft. Il est sorti en 2006 sur Windows, Game Boy Advance et Nintendo DS.', 'https://fr.wikipedia.org/wiki/L%C3%A9a_Passion_:_V%C3%A9t%C3%A9rinaire'),
  ('Q28501087', 'The King of Fighters EX: Neo Blood est un jeu vidéo de combat développé par Artoon et édité par Sammy Studios, sorti en 2002 sur Game Boy Advance. Il a pour suite The King of Fighters EX2: Howling Blood.

C''est une adaptation de The King of Fighters ''99: Millennium Battle.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_EX:_Neo_Blood'),
  ('Q28127188', 'Hot Wheels: Burnin'' Rubber est un jeu vidéo de course développé par Altron et édité par THQ, sorti en 2001 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Hot_Wheels:_Burnin%27_Rubber'),
  ('Q28496672', 'Alienators: Evolution Continues est un jeu vidéo d''action développé par Digital Eclipse et édité par Activision sur Game Boy Advance. Il est basé sur la série animée du même nom, elle-même issue du film Évolution.', 'https://fr.wikipedia.org/wiki/Alienators:_Evolution_Continues_(jeu_vid%C3%A9o)'),
  ('Q28499085', 'Teen Titans 2 est un jeu vidéo d''action développé par Artificial Mind and Movement et édité par Majesco Entertainment, sorti en 2006 sur Game Boy Advance. Il est basé sur la série d''animation Teen Titans: Les Jeunes Titans. Il s''agit de la suite de Teen Titans.', 'https://fr.wikipedia.org/wiki/Teen_Titans_2'),
  ('Q48081885', 'Altered Beast: Guardian of the Realms est un jeu vidéo de type beat them all développé par 3d6 Games et édité par Sega, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Altered_Beast:_Guardian_of_the_Realms'),
  ('Q48349442', 'Droopy''s Tennis Open est un jeu vidéo de sport (tennis) développé par Bit Managers et édité par LSP Games, sorti en 2002 sur Game Boy Advance.

Il met en scène Droopy, chien créé anthropomorphe créé par Tex Avery.', 'https://fr.wikipedia.org/wiki/Droopy%27s_Tennis_Open'),
  ('Q52158532', 'Punch King est un jeu vidéo de combat de boxe anglaise développé par Full Fat et édité par Acclaim Entertainment, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Punch_King'),
  ('Q35881040', 'Dungeons and Dragons: Eye of the Beholder est un jeu vidéo de rôle développé par Pronto Games et édité par Infogrames, sorti en 2002 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Dungeons_and_Dragons:_Eye_of_the_Beholder'),
  ('Q58106199', 'Boulder Dash EX est un jeu vidéo d''action et de labyrinthe développé par Vision Works et édité par Kemco, sorti en 2002 sur Game Boy Advance.

Il fait partie de la série Boulder Dash.', 'https://fr.wikipedia.org/wiki/Boulder_Dash_EX'),
  ('Q55452719', 'Whac-A-Mole est un jeu vidéo d''action (jeu de la taupe) développé par DC Studios et édité par Activision, sorti en 2005 sur Game Boy Advance et Nintendo DS.', 'https://fr.wikipedia.org/wiki/Whac-A-Mole_(jeu_vid%C3%A9o,_2005)'),
  ('Q54938490', 'Jet Set Radio, abrégé JSR, aussi connu sous le nom de Jet Grind Radio ou JGR en Amérique du Nord, est un jeu vidéo d''action développé par Vicarious Visions et édité par THQ en Amérique du Nord où il est sorti le 1er juin 2003. Une version européenne voit le jour le 20 février 2004, éditée par Sega Europe et distribuée par Atari Europe.

Exclusif à la Game Boy Advance, le jeu s''inspire de Jet Set Radio, sorti en 2000 sur Dreamcast. Il bénéficie du même moteur que celui déjà utilisé par Vicarious Visions à l''époque de son portage de Tony Hawk''s Pro Skater 2 sur Game Boy Advance, offrant une vue isométrique du dessus.', 'https://fr.wikipedia.org/wiki/Jet_Set_Radio_(jeu_vid%C3%A9o,_2003)'),
  ('Q63479640', 'Alexandra Ledermann est un jeu vidéo d''équitation développé par Independent Arts et édité par Ubisoft, sorti en 2003 sur Game Boy Advance.

